  ('osm', '805133237', 'Meadow Valley Motocross', 'track', 44.320401, -92.256091, 'MN', 'Wabasha County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '819211448', 'Elk Park Cut-Off Road', 'park', 38.115210, -106.829113, 'CO', 'Saguache County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '826560806', 'Holly Oaks ORV Park', 'park', 42.829216, -83.571588, 'MI', 'Oakland County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '847932402', 'Muddy Bottoms ATV & Recreation Park', 'park', 32.959387, -93.486538, 'LA', 'Webster County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '85774731', 'PCLL - Mud Hole', 'park', 39.433810, -105.461211, 'CO', 'Park County County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '865088067', 'Rio Bravo Motocross Park', 'track', 29.890272, -95.234323, 'TX', 'Harris County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '894950977', 'Big Air Motocross', 'track', 43.425623, -85.834266, 'MI', 'Newaygo County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '895096292', 'Redbud Professional Motocross Track', 'track', 41.869977, -86.370212, 'MI', 'Berrien County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '911479625', 'Glen Helen Off Highway Vehicle Park', 'park', 34.191378, -117.389082, 'CA', 'San Bernardino County County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '916038685', 'Jewell Motocross', 'track', 39.689338, -104.636273, 'CO', 'Arapahoe County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '932526048', 'Muddy Waters Motorsports Park', 'park', 41.539422, -90.338933, 'IL', 'Rock Island County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('osm', '980672048', 'Millpond Motocross Park', 'track', 48.375708, -115.535496, 'MT', 'Lincoln County', null, null, '{}'::text[], 'ODbL 1.0', '© OpenStreetMap contributors'),
  ('usfs', '10632', 'Railroad Buttes OHV Area', 'ohv_area', 43.905900, -102.860300, null, 'Nebraska National Forests and Grasslands', 'Railroad Buttes area is one of a few large, open off-road riding areas on Forest Service lands, covering approximately 3 square miles. The open play area includes hill climbs, multiple trails and makeshift motocross tracks. Most of the terrain is hard packed and can get dusty and there is little to no shade. There is a large parking/staging area with plenty of space. Dispersed camping is allowed but there is no potable water. Fireworks and shooting are prohibited. There are no fees or permits required at this time. Please recreate with respect and pack out all trash.', 'https://www.fs.usda.gov/recarea/nebraska/recarea/?recid=10632', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '10744', 'Sugar Creek Multiuse', 'trail_system', 34.426000, -94.056000, null, 'Ouachita National Forest', 'The Sugar Creek Multi-Use Trail is a network of looping trails that winds over various types of terrain and through a variety of tree types. Connecting loops offer users an opportunity to explore exciting outdoor opportunities. The Sugar Creek Multi Use Recreation Trail offers motorcycle, 4-wheeler, utility vehicle, horse, bicycle, and foot travel enthusiasts approximately 30 miles of rustic, scenic, historic and picturesque travel ways. The difficulty level ranges from easy to more difficult, with most of the trail being easy to moderate difficulty.', 'https://www.fs.usda.gov/recarea/ouachita/recarea/?recid=10744', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '10797', 'Wolf Pen Gap', 'trail_system', 34.492944, -94.169889, null, 'Ouachita National Forest', 'Featuring high mountain vistas, the trail leads the rider through an array of areas, including scenic Gap Creek and Board Camp Creek. The trail continues through a forest of large pines and hardwoods before passing the unique 2-footed oak tree and an abandoned mine shaft. The trail loops are connected to accommodate riders who want to vary the length of their trips. Wolf Pen Gap Trail Map and Information Geo-referenced trail map of the Wolf Pen Gap trail system. Link to the Wolf Pen Gap Trail map on Avenza', 'https://www.fs.usda.gov/recarea/ouachita/recarea/?recid=10797', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '10978', 'Ballinger Campground', 'trail_system', 34.883333, -119.444444, null, 'Los Padres National Forest', 'Badlands terrain - All Terrain Vehicle and motorcycle use area. There are 13 campsites. 9 sites are available on the reservation system. 3 campsites are on a first-come, first- serve basis. In campgrounds and picnic areas, dogs mst be kept on a leash. Dogs must wear a collar with current tags at all times, as state and county laws apply on National Forest System lands.', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=10978', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11016', 'Ballinger Canyon OHV Day Use Riding Area', 'trail_system', 34.883333, -119.444444, null, 'Los Padres National Forest', 'The Ballinger and Deer Park areas are geared toward OHV use. These areas provide 11 4WD roads, 12 ATV trails, and 14 motorcycle trails. Access to 4WD roads is available to both ATVs and motorcycles, and access to ATV trails is available to motorcycles. Red sticker riding season Oct. 1 - April 30.', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=11016', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11055', 'Nordhoff Ridge Road', 'trail_system', 34.498060, -119.242180, null, 'Los Padres National Forest', 'Nordhoff Ridge Trail - open from Rose Valley Side (Gate combination needed to enter). Sisar Gate side closed. Travel routes open: Rose Valley to Sisar Gate (open), Rose Valley to Fire Tower open, but experienced 4-wheel-drive operators only. General Information Nordhoff Ridge Road is a street legal 4-wheel-drive road. Open by permit only approximately May 15 - December 15. Nordhoff Ridge Rd is a wide and hard-packed 4 x 4 Road that is approximately 10 miles long. The road has a few steep climbs but features some stunning views of the surrounding mountain ranges and Valley. Dispersed camping…', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=11055', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11104', 'Divide Peak OHV Trailhead', 'trailhead', 34.481800, -119.577800, null, 'Los Padres National Forest', 'Offers views of Santa Barbara coastline, Upper Santa Ynez Valley and San Rafael Mountains. Divide Peak Road is approximately 17 miles on East Camino Cielo from Highway 154. The parking lot for the OHV road is on the right side of East Camino Cielo 12.5 miles from Highway 154.', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=11104', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11111', 'Baja Campground', 'trail_system', 35.139000, -120.137800, null, 'Los Padres National Forest', 'Large oak-shaded camp on the banks of Alder Creek.', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=11111', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11126', 'La Panza Campground', 'trail_system', 35.353300, -120.260300, null, 'Los Padres National Forest', 'Nestled in large grove of oaks. Close proximity to off-highway vehicle opportunities and access to Machesna Mountain Wilderness. Recreational vehicles no longer than 16 feet. There are 9 campsites. Reservations: 7 sites are now on the reservation system: www.recreation.gov or by calling 1-877-444-6777. (2 campsites) are on a first-come, first- serve basis. The La Panza Campground is no longer an Adventure Pass Campground. This campground is managed by the Parks Management for the Forest Service. No drinking water at the campground. Bring your own water.', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=11126', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11129', 'Navajo Flat OHV Staging Area and campsites', 'trailhead', 35.379000, -120.284100, null, 'Los Padres National Forest', 'Primitive campground with six campsites, 5 have shade structures. Fire rings and pedestal BBQ grills. Beginners OVH riding area. Reservations: 5 sites are now on the reservation system: www.recreation.gov or call 1-877-444-6777. (1) campsite is on a first-come, first- serve basis. The Navajo Flat OHV Staging Area with campsites is no longer an Adventure Pass Campground. This campground is managed by the Parks Management for the Forest Service. $30/night, $10/extra vehicle fee. Bring your own water and firewood. Please pack your trash out.', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=11129', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11763', 'Genoa Peak Road 14N32', 'trail_system', 39.027060, -119.895930, null, 'Lake Tahoe Basin Management Unit', 'Genoa Peak Road (14N32) is located on National Forest lands on the East Shore of Lake Tahoe and is typically accessible beginning Memorial Day through Nov. 15, weather permitting. This National Forest Road traverses the Carson Range from north to south and can be reached from Kingsbury Grade on the south end or Spooner Summit to the north. Genoa Peak Road offers miles of hiking and OHV trails with spectacular views of Lake Tahoe and the Carson Valley. Campfires (wood, charcoal or any other solid fuels) are not permitted. Portable stoves that have an on/off switch or valve are allowed with a…', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11763', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11765', 'Kingsbury Stinger 18E39.3', 'trail_system', 38.972810, -119.910570, null, 'Lake Tahoe Basin Management Unit', 'The Kingsbury Stinger Trail (18E39.3) is located on National Forest lands on the East Shore of Lake Tahoe. This recreational trail runs 2.75 miles from Genoa Peak road (14N32) to Terrace View Drive on Kingsbury Grade and is designed for OHV s that are 50 or less. The trail is managed for ATV , motorcycle and mountain bike use and is highly used by those use types as well as local area hikers/pedestrians, and provides an important connection and loop option, particularly for motorized users.', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11765', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11789', 'Fountain Place', 'trail_system', 38.869200, -119.987200, null, 'Lake Tahoe Basin Management Unit', 'Fountain Place', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11789', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11793', 'Saxon Creek', 'trail_system', 38.875000, -119.984500, null, 'Lake Tahoe Basin Management Unit', 'Saxon Creek', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11793', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11804', 'Sand Pit OHV Area (12N28)', 'ohv_area', 38.899500, -120.009500, null, 'Lake Tahoe Basin Management Unit', 'The Sand Pit OHV area is located near South Lake Tahoe off of Lake Tahoe Boulevard across from South Tahoe High School. Off-Highway Vehicles are permitted. Campfires (wood, charcoal or other solid fuels) are not permitted.', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11804', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11805', 'Sawmill Pond Picnic Area', 'trail_system', 38.889100, -120.025900, null, 'Lake Tahoe Basin Management Unit', 'Sawmill Pond is a stocked fishing area for children 14 years of age and under. Adults are allowed to help children fish but not allowed to fish themselves. The pond is located approximately one mile south of South Lake Tahoe along Lake Tahoe Boulevard. Restrooms and picnic tables are available in the summer. Campfires (wood, charcoal or any other solid fuels) are not permitted. Portable stoves with an on/off switch are allowed with a valid permit .', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11805', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11807', 'Power Line Road 12N08', 'trail_system', 38.872000, -119.986000, null, 'Lake Tahoe Basin Management Unit', 'Power Line Road 12N08', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11807', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11810', 'Hellhouse Road 12N01D', 'trail_system', 38.866200, -119.989500, null, 'Lake Tahoe Basin Management Unit', 'Hellhouse Road 12N01D', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11810', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11830', 'Noonchester 14N34A', 'trail_system', 39.058300, -120.158800, null, 'Lake Tahoe Basin Management Unit', 'The Noonchester Trail is a Motorcycle, ATV and 4x4 road. The difficulty is considered moderate. The length of the road is 2.65 miles.', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11830', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '11831', 'Buck Lake Road 14N40', 'trail_system', 39.048400, -120.176000, null, 'Lake Tahoe Basin Management Unit', 'Buck Lake Road 14N40', 'https://www.fs.usda.gov/recarea/ltbmu/recarea/?recid=11831', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12112', 'Anthony Flat Trailhead', 'trailhead', 38.993322, -111.636737, null, 'Fishlake National Forest', 'Anthony Flat Trailhead is in a beautiful meadow with conifer and aspen trees around the edges for shade. There is a vault restroom, and an information kiosk. Camping, hunting, wildlife viewing, hiking, and OHV riding on designated routes are fun activities. The trailhead is over 7,700 feet in elevation so come prepared for cool temperatures and mountain conditions. Please pack-out what you pack-in.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12112', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12117', 'BETENSON FLAT TRAILHEAD', 'trailhead', 38.238608, -112.386900, null, 'Fishlake National Forest', 'Betenson Flat Trailhead is located south of State Road 137 off Forest Road 151 on the Paiute Trail.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12117', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12118', 'BICKNELL BOTTOMS GWT TRAILHEAD', 'trailhead', 38.310509, -111.517869, null, 'Fishlake National Forest', 'Trailhead - Great Western Trail segment.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12118', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12121', 'BIG JOHN''S FLAT CUA DISPERSED', 'trail_system', 38.344329, -112.399934, null, 'Fishlake National Forest', 'Dispersed Camping Area Located just south of the Tushar Mountain Peaks, Big John Flat area is a favorite recreational spot because of its large meadows that have spectacular scenery. This area also offers opportunities for winter sport enthusiasts such as snowmobiling and cross-country skiing. Common vegetation includes Engelmann spruce, aspen and fir stands with large meadows. The general terrain is a large meadow encompassed by trees. This area is open to ATV use on designated roads and trails. Please help prevent erosion and soil compaction by staying on roads and main driving trails.…', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12121', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12128', 'BOSMAN-BIG JOHN FLAT TRAILHEAD', 'trailhead', 38.353529, -112.394365, null, 'Fishlake National Forest', 'This trailhead provides access to the Paiute 01 ATV trail. About a half mile to the north, Skyline-Big John Flat Trailhead provides access to the Skyline National Recreation Trail as well as the Piute 01 ATV trail. About a mile to the south, Big John''s Flat dispersed camping area provides access to Trailhead #068. Approximately 1 mile west of the dispersed camping area you will find yourself at an intersection of three different trails. To the south is trail #064. To the north you can take trail #172 (Shelley Baldy Creek Trail). If you stay on this trail heading north you will end in the…', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12128', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12137', 'CITY CREEK TRAILHEAD', 'trailhead', 38.269679, -112.311055, null, 'Fishlake National Forest', 'Trailhead #071. This horse and foot trail heads northwest out of City Creek Campground for approximately three miles where it will intersect trail #225 which is the Skyline Trail. If you head south on #225 you will reach Big Flat. If you head north you will reach the #219 Lake Stream Trailhead.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12137', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12148', 'MAX REID (PAIUTE) TRAILHEAD', 'trailhead', 38.576574, -112.335269, null, 'Fishlake National Forest', 'Trailhead #01. The Dry Creek Trail Paiute #01 Trail is accessed via Forest Road #475. This ATV trail heads south along Dry Creek where it eventually turns into a very rough mostly ATV trail. If you stay on forest Road #475 it will turn into Forest Road #476 taking you into the upper elevations of Sargent Mountain.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12148', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12155', 'FISH CREEK TRAILHEAD', 'trailhead', 38.193975, -111.401294, null, 'Fishlake National Forest', 'Generally considered a moderately challenging route.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12155', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12170', 'HOGAN PASS TRAILHEAD', 'trailhead', 38.581509, -111.478654, null, 'Fishlake National Forest', 'This trail is closed in higher elevations.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12170', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12177', 'JIMMY REED TRAILHEAD', 'trailhead', 38.296429, -112.439233, null, 'Fishlake National Forest', 'Trailhead #124. Located on PST 05, this trail leads to the west toward Mud Flat and eventually (if you continue along this trail) it will take you to the Face Trail and down into Beaver, Utah. Points of interest include the Ice Caves and the South Fork of North Creek overlook.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12177', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12183', 'Koosharem Canyon/Paiute ATV Trailhead', 'trailhead', 38.528400, -111.913828, null, 'Fishlake National Forest', 'Koosharem Canyon/Paiute ATV Trailhead is located at an elevation of about 7,400 feet with pinyon and juniper trees for shade. Facilities include a vault restroom, information kiosk, picnic table, gravel parking, and dispersed camping sites. ATV riding on the Paiute 01 ATV trail and other designated routes are available. Please pack-out what you pack-in. Camping stay limit is 16 days.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12183', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12193', 'LEBARON TRAILHEAD', 'trailhead', 38.230049, -112.394357, null, 'Fishlake National Forest', 'The Lebaron ATV Trail is just west of Lebaron Campground on Forest Road #147 and is a jumping-off point to numerous loop trails and ATV Forest Roads. If you take Forest Road #147 (PST 88) it will take you north for approximately 8 to 10 miles, winding its way through Strawberry Flat and eventually down to Three Creeks Reservoir. North of the Three Creek Dam is the junction with PST 05 and east of there about .5 mile is the Piute 01 Trail.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12193', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12198', 'Lower Box Creek Trailhead', 'trailhead', 38.447092, -111.962636, null, 'Fishlake National Forest', 'Lower Box Creek Trailhead is located at an elevation of over 7,000 feet in a canyon along Greenwich Creek with cottonwood trees for shade. Facilities include an unloading ramp, information kiosk and vault restroom. Paiute Side Trail 53 begins at the trailhead and allows 50" ATVs. Dispersed camping, hiking, horseback riding, hunting, and wildlife viewing are fun activities. Please stay on designated routes and pack-out what you pack-in. Camping stay limit is 16 days.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12198', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12210', 'Middle Box Creek Trailhead', 'trailhead', 38.483811, -112.002364, null, 'Fishlake National Forest', 'Middle Box Creek Trailhead is located along FR068 in a high elevation (9,000 feet) meadow with aspen trees for shade. Facilities include parking and a vault restroom. Hunting, wildlife viewing, and OHV riding on designated routes is available. Box Creek reservoir provides a fishing opportunity. Please pack-out what you pack-in.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12210', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12213', 'Milo''s Kitchen Trailhead', 'trailhead', 38.532956, -111.952681, null, 'Fishlake National Forest', 'Milo''s Kitchen Trailhead is in a small meadow along FR076 at an elevation of about 8,700 feet with aspen and conifer trees for shade. The trailhead provides access to the Paiute 01 and PST33 50" ATV trails. Facilities include vault restroom, and a information kiosk. Popular activities in the area are hiking, wildlife viewing, hunting, and OHV riding on designated routes. Please pack-out what you pack-in.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12213', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12222', 'Oak Ridge Trailhead', 'trailhead', 38.832686, -111.665206, null, 'Fishlake National Forest', 'Oak Ridge Trailhead is found on an old drill pad on a windswept ridge at an elevation of nearly 8,700 feet. Facilities include a gravel parking lot, information kiosk, and vault restroom. The Great Western Trail for 50" ATVs, horseback riding, and hiking passes through the trailhead. Popular activities include dispersed camping, hunting, wildlife viewing, and OHV riding on designated routes. Please pack-out what you pack-in. Camping stay limit is 16 days.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12222', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12226', 'PLANTATION FLATS CAMPING AREA', 'trail_system', 39.356016, -112.225149, null, 'Fishlake National Forest', 'Dispersed camping Area. Facilities include vault toilet in the area.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12226', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12243', 'Sheep Creek Trailhead', 'trailhead', 38.799814, -111.669818, null, 'Fishlake National Forest', 'Sheep Creek Trailhead is on the north side of the Gooseberry Road 640 at an elevation of about 8,300 feet. Facilities include a large gravel parking lot, information kiosk, and vault restroom. Gooseberry trails for 50" ATVs, horseback riding, and hiking opportunities begin at the trailhead. Other popular activities include, hunting, wildlife viewing, and OHV riding on designated routes. Please pack-out what you pack-in. No camping is allowed at the trailhead.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12243', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12251', 'SOUTH CREEK (LOWER) TRAILHEAD', 'trailhead', 38.175665, -112.504681, null, 'Fishlake National Forest', 'Trailhead. This trailhead provides access to PST #068, one of the most used and popular side trails of the Paiute Trail System. It is strictly limited for ATVs that are 50" or less. This trail is narrow and very rough in certain areas. Trail PST #068 also provides access to five horse and foot trails in the south Creek drainage.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12251', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12259', 'TIMID SPRINGS TRAILHEAD', 'trailhead', 38.301634, -112.358290, null, 'Fishlake National Forest', 'Trailhead. This trailhead is located in the middle of PST 29, north of the Big Flat dispersed camping area. The trailhead is open to four wheel drive vehicles, ATV''s, horses, and foot travel. The greatest number of users are ATV riders.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12259', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12260', 'SAND CREEK GWT TRAILHEAD', 'trailhead', 38.309514, -111.432048, null, 'Fishlake National Forest', 'A trail open in lower elevations only.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12260', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12268', 'Upper Box Creek Trailhead', 'trailhead', 38.478281, -112.003181, null, 'Fishlake National Forest', 'Upper Box Creek Trailhead is located on a point overlooking Upper Box Creek reservoir at an elevation of nearly 8,900 feet. There is a vault restroom, information kiosk, and gravel parking. Upper Box Creek can be a great fishing opportunity, plus there is wildlife viewing, hunting, hiking, and OHV riding on designated routes. Please pack-out what you pack-in.', 'https://www.fs.usda.gov/recarea/fishlake/recarea/?recid=12268', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12898', 'Sugar Creek Upper Trailhead', 'trailhead', 39.322018, -105.129043, null, 'Pike-San Isabel National Forests', 'The Noddles Trail (#677) is one of the many OHV (Off Highway Vehicle) trails in the Rampart Range Recreation Area. These trails are designated for vehicles 50" or less in width.', 'https://www.fs.usda.gov/recarea/psicc/recarea/?recid=12898', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12899', 'Sugar Creek Lower Trailhead', 'trailhead', 39.301341, -105.172706, null, 'Pike-San Isabel National Forests', 'The Noddles Trail (#677) and Log Jumper Trail (#677.A) are one of the many OHV (Off Highway Vehicle) trails in the Rampart Range Recreation Area. These trails are designated for vehicles 50" or less in width.', 'https://www.fs.usda.gov/recarea/psicc/recarea/?recid=12899', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12918', 'Cabin Ridge Trailhead', 'trailhead', 39.281741, -105.104012, null, 'Pike-San Isabel National Forests', 'Situated along the Rampart Range Road south of Highway 67, the Cabin Ridge Trailhead is located southeast of the Cabin Ridge Picnic Area. Cabin Ridge Trailhead accesses Cabin Ridge Trail (#675).', 'https://www.fs.usda.gov/recarea/psicc/recarea/?recid=12918', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12930', 'Dutch Fred Trailhead', 'trailhead', 39.285735, -105.091960, null, 'Pike-San Isabel National Forests', 'The Dutch Fred Trailhead is located south of Indian Creek along the Rampart Range Road. The Dutch Fred Trail (#679) enters into a a system of 115 miles of motorcycle and ATV trails in the Rampart Range Recreation Area. In order to use any vehicle on National Forest lands, it must either have a valid state license plate or be registered with the Colorado Off-Highway Vehicle (OHV) Program. Contact Colorado State Parks at 303-866-3437 for OHV registration information. Registered OHVs may be subject to fines if used where they are not specifically permitted.', 'https://www.fs.usda.gov/recarea/psicc/recarea/?recid=12930', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12931', 'Flat Rocks Campground', 'trail_system', 39.327485, -105.092205, null, 'Pike-San Isabel National Forests', 'Hidden in the Rampart Range, Flat Rocks is an ideal campground for ATV and motorcycle riders in the Rampart Range Recreation Area. ATVs and off-road motorcycles are allowed to enter and depart the campground for trail access. Consult the current Motor Vehicle Use Map (MVUM) for specific roads and trails open to off-road vehicles. There is no dump station or hook-up available. All dates are weather dependent. Visitors may expect full service between Memorial Day weekend and Labor Day weekend The area also has an extended season when services such as water, trash or a host may not be available…', 'https://www.fs.usda.gov/recarea/psicc/recarea/?recid=12931', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12933', 'Flat Rocks Trailhead', 'trailhead', 39.327282, -105.086922, null, 'Pike-San Isabel National Forests', 'The Flat Rocks Trailhead is located south of Indian Creek along the Rampart Range Road. The Flatrock Trail (#674) trail enters into a system of 115 miles of motorcycle and ATV trails in the Rampart Range area.', 'https://www.fs.usda.gov/recarea/psicc/recarea/?recid=12933', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12936', 'Garber Creek Trailhead', 'trailhead', 39.358130, -105.078715, null, 'Pike-San Isabel National Forests', 'The Garber Creek Trailhead is located south of Indian Creek. The Garber Creek Trail (#686) enters into a system of 115 miles of motorcycle and ATV trails in the Rampart Range Recreation Area.', 'https://www.fs.usda.gov/recarea/psicc/recarea/?recid=12936', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12947', 'Hall Valley Campground', 'trail_system', 39.482971, -105.805362, null, 'Pike-San Isabel National Forests', 'This campground has nine campsites at an elevation of 9,900 feet with parking spur lengths of 16-30 feet. Facilities include picnic tables, a vault toilet and fire rings. All dates are weather dependent. Visitors may expect full service from Memorial Day weekend to Labor Day weekend. The area also has an extended season when services such as water, trash or a host may not be available during the fall/winter/spring.', 'https://www.fs.usda.gov/recarea/psicc/recarea/?recid=12947', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '12948', 'Handcart Campground', 'trail_system', 39.482365, -105.799906, null, 'Pike-San Isabel National Forests', 'Off Park County Route 60, from US Hwy 285, the Handcart campground is surrounded by lodgepole pine trees. The campground has 10 campsites for TENT CAMPING ONLY. All dates are weather dependent. Visitors may expect full service from Memorial Day weekend to Labor Day weekend. The area also has an extended season when services such as water, trash or a host may not be available during the fall/winter/spring.', 'https://www.fs.usda.gov/recarea/psicc/recarea/?recid=12948', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '14909', 'Black Springs OHV Area', 'ohv_area', 38.377919, -120.196111, null, 'Stanislaus National Forest', 'The Black Springs OHV network on the north side of Highway 4 is the main Off-Highway Vehicle riding area on the Calaveras Ranger District. With over 100 miles of connecting roads and trails, there is enjoyable riding for all levels and types of users, including four-wheel drive, all-terrain vehicles, and motorcycles. The trail network is generally accessible to Off-Highway Vehicles from early summer to fall; during the winter months, portions of the network are available for use by Over-Snow Vehicles. A map showing recommended routes is available upon request from the Ranger District Office.', 'https://www.fs.usda.gov/recarea/stanislaus/recarea/?recid=14909', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '15001', 'Crandall / Deer Creek', 'trail_system', 38.160830, -120.132750, null, 'Stanislaus National Forest', 'A popular motorcycle riding area with 40 miles of signed trails and 140 miles of road open to OHV use extending from north of Crandall Peak to the Deer Creek area northwest of Highway 108. The riding area ranges in elevation of 3,500 feet at Deer Creek to 5500 feet at Crandall Peak. Four-wheel drive and ATV trails are limited, but use is allowed on the 140 miles of road. A camping area located at Crandall Peak near Spring Gap off Forest Roads 4N01 and 4N88, accesses these routes and offers dispersed camping and vehicle parking/off loading with restrooms, but no other services or potable water…', 'https://www.fs.usda.gov/recarea/stanislaus/recarea/?recid=15001', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '15003', 'Hull Creek / Trout Creek', 'trail_system', 38.105200, -120.037100, null, 'Stanislaus National Forest', 'The Hull and Trout Creek area southeast of Long Barn is a popular area for ATV and four-wheel drive users to operate with 20 miles of signed trails and 100 miles of roads open to OHV use. Unlike the Crandall and Deer Creek area, few single-track motorcycle trails currently exist. The riding area ranges in elevation of 4500 feet near Long Barn to 7600 feet at Bourland Mountain. The riding area is closed during the winter due to snow blocking access. Hull Creek campground is nearby with 23 units, restrooms, and drinking water. Adjacent areas offer no-service, dispersed camping opportunities.…', 'https://www.fs.usda.gov/recarea/stanislaus/recarea/?recid=15003', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '15005', 'Hunter Creek', 'trail_system', 37.939300, -120.157800, null, 'Stanislaus National Forest', 'The Hunter Creek area east of Tuolumne City on the south end of the Mi Wok Ranger District offers 100 miles of roads open to OHV use. Future site specific analysis may result in trail opportunities being developed. The riding area ranges in elevation of 2500 feet at Hunter Creek to 5800 feet at Duckwall Mountain. The riding area is open all year, but access on some roads may be blocked due to snow in winter months. River Ranch Campground off Cottonwood Road offers full service camping facilities near the riding area seasonally. The campground is open March 1- November 1. OHV use is not…', 'https://www.fs.usda.gov/recarea/stanislaus/recarea/?recid=15005', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '15043', 'Niagara OHV Campground', 'trail_system', 38.310793, -119.890315, null, 'Stanislaus National Forest', 'var $j = jQuery;$j.noConflict();$j(window).load(function() {$j(''#slider'').nivoSlider( {effect: ''fade'',startSlide: 0,animSpeed: 750,pauseTime: 8000});}); Niagara OHV Campground situated in a mixed conifer forest. It is located on Forest Road 5N01. Turn right off of Highway 108 at Eagle Meadow Road (5N01), about 15 miles from the Summit Ranger Station and follow Eagle Meadow Road approximately 3 miles to the campground. There are 10 sites; each site has a table and a fire ring. The main road and parking pads are dirt-surfaced. Potable water is not available. Toilets are vault-style. Fee charged…', 'https://www.fs.usda.gov/recarea/stanislaus/recarea/?recid=15043', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '18936', 'Mack Lake ORV Campground', 'trail_system', 44.578778, -84.064904, null, 'Huron-Manistee National Forests', 'The 175-acre lake is surrounded by rolling jack pine plains and is a good location for wildlife viewing. The campground is primarily used by ORV trail riders. Flickr Photo Album', 'https://www.fs.usda.gov/recarea/hmnf/recarea/?recid=18936', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '18948', 'Bull Gap ORV Hill Climb and Trailhead', 'trailhead', 44.616637, -84.027047, null, 'Huron-Manistee National Forests', 'Bull Gap Hill Climb is the ONLY designated motorized ''Open Area Riding'' on the Huron-Manistee National Forest. The sand hill is 0.2 mile and at a 35 - 40% grade. Bull Gap is open to all vehicles with a valid DNR ORV trail sticker. If you chose to use hill climb in a vehicle 50 wide or less, you are required to use the 50 return trail to return to the bottom of the hill. Users in motor vehicles greater than 50 are required to use the full-size motorized vehicle return route.', 'https://www.fs.usda.gov/recarea/hmnf/recarea/?recid=18948', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '18954', 'Meadows ORV Complex', 'trail_system', 44.559172, -84.308336, null, 'Huron-Manistee National Forests', 'This trail system connects to the Mack Lake Trail System and was developed for vehicles 50 in. or less. As riders travel through the forest they will see a wide variety of scenery types. The trail ranges anywhere from 0 to 10% grades with some short stretches of 30%. Confidence markers are orange triangles. This trail is shown on the Huron-Manistee National Forests Motor Vehicle Use Map, available in the Maps and Publications section. A map is also located on the MI-DNRE website .', 'https://www.fs.usda.gov/recarea/hmnf/recarea/?recid=18954', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '18958', 'Meadows ORV Campground', 'trail_system', 44.559264, -84.309164, null, 'Huron-Manistee National Forests', 'Meadows Campground is a small, 16 single site area primarily used by OHV riders and is first-come, first-served. The sites accomodate trailers/RV''s up to 25 feet in length. The campground has drinking water and a trailhead for the Meadows Trail.', 'https://www.fs.usda.gov/recarea/hmnf/recarea/?recid=18958', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '22620', 'Weston Recreation Area', 'ohv_area', 44.640970, -105.340990, null, 'Medicine Bow-Routt NFs and Thunder Basin NG', 'This popular recreation area is located on the Thunder Basin National Grassland, about 30 miles north of Gillette via State Highway 59, and is accessible year-round. There are 15 miles of looping Off-Highway Vehicle (OHV) trails that cross over 3,000 acres of public land jointly managed by the Forest Service, Bureau of Land Management (BLM) and the Wyoming State Trust. These trails offer varying degrees of difficulty from beginner to the more experienced rider and include 2 trail bridges and hill climbs. The majority of the trails are only open to OHVs less than 60 inches in length on BLM…', 'https://www.fs.usda.gov/recarea/mbr/recarea/?recid=22620', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '23068', 'Ute Heart Trailhead', 'trailhead', 40.055210, -107.031200, null, 'Medicine Bow-Routt NFs and Thunder Basin NG', '* The Ute-Heart Trail No. #1110 is generally not reachable or melted off until late June/early July due to snow levels at this elevation. This one way 6.85 mile ATV trail is very narrow and rocky with uneven terrain making it a difficult, technical trail that is best for experienced riders. In addition, the trail also has steep drop-off''s that offer beautiful vista views of the Bear Corridor. The trail begins by descending down for the first .2 miles where you will cross a narrow bridge that is 50 inches wide, however, it is important to note that the bolts and hardware on the inside of the…', 'https://www.fs.usda.gov/recarea/mbr/recarea/?recid=23068', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '23072', 'Morrison Divide South Trailhead', 'trailhead', 40.106990, -106.687430, null, 'Medicine Bow-Routt NFs and Thunder Basin NG', 'This Trailhead serves as one of two access points to the Morrison Divide Trail No. 1774. This 13.3 mile route climbs Green Ridge and grants access to the Muddy Slide overlook at an elevation of 10,258 feet. This stopping point offers spectacular views of the Morrison Creek Valley to the East and overlooks the Muddy Slide, a historic landslide. The trail experiences heavy ATV/OHV use during hunting season and is popular with hikers and mountain bikers during summer months. This trail is closed to any vehicles over 50 in width. Please tread lightly and do not ride off the designated route.…', 'https://www.fs.usda.gov/recarea/mbr/recarea/?recid=23072', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '26347', 'Pinnacles OHV Staging Area', 'trailhead', 34.298056, -117.202778, null, 'San Bernardino National Forest', 'OHV Staging area on SR 173 north of Lake Arrowhead. There is a vault toilet and a picnic tables at the staging area along with ample parking and informational signs.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=26347', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '26363', 'Cactus Flat OHV Staging Area', 'trailhead', 34.300556, -116.797778, null, 'San Bernardino National Forest', 'Cactus Flat OHV Staging Area is off of Highway 18, north of Big Bear and south of Lucerne Valley. Look for Forest Road 3N03 and go southeast, following the signs to the staging area. There is a vault toilet and a couple of picnic tables at the staging area along with ample parking and informational signs.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=26363', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '26547', 'Summit OHV Staging Area', 'trailhead', 34.321042, -117.429972, null, 'San Bernardino National Forest', 'This staging area has ample parking, a few unshaded picnic tables, and trash cans. Forest Road 3N22 south of the staging area is for Red/Green sticker OHV ''s and High-clearance 4WD vehicles with license plates. 3N22 connects to the Cleghorn Ridge Road 2N47. NO OHV Camping permitted due to Forest Order 05-12-00-23-05 OCCUPANCY AND USE', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=26547', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '26549', 'Baldy Mesa (Trestles) OHV Staging Area', 'trailhead', 34.331944, -117.477222, null, 'San Bernardino National Forest', 'This staging area has ample parking, vault toilets, trash cans, and a few unshaded picnic tables. Forest Road 3N21 north of the staging area is for Red/Green sticker OHV `s and High-clearance 4WD vehicles with license plates. 3N21 connects to the Baldy Mesa Road 3N24. OHV maps available at Lytle Creek Ranger Station', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=26549', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '28234', 'Coney Flats Trailhead', 'trailhead', 40.130138, -105.576448, null, 'Arapaho & Roosevelt National Forests Pawnee NG', 'Coney Flats Trailhead is at the west end of Coney Creek Road, approximately 3.5 miles west of Beaver Reservoir. Coney Creek Road is a rough, native-surface road for experienced four-wheel-drivers only. There is a deep stream crossing that may be impassable at times, just east of Coney Flats. Parking is limited. The free Boulder Ranger District Motor Vehicle Use Map displays National Forest System (NFS) routes open to motorized travel and is available online. The Coney Creek Road is open seasonally. For current information on road openings and closures, check the road status table . View an…', 'https://www.fs.usda.gov/recarea/arp/recarea/?recid=28234', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '29144', 'Pole Creek Trailhead #820', 'trailhead', 37.761990, -107.466610, null, 'Rio Grande National Forest', 'near the headwaters of the Rio Grande River', 'https://www.fs.usda.gov/recarea/riogrande/recarea/?recid=29144', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '29208', 'Tewksberry Trailhead #842', 'trailhead', 37.561148, -106.690211, null, 'Rio Grande National Forest', 'Tewksberry Trail makes a gentle ascent over scenic Meadow Pass between Cattle Mountain and Demijohn Peak. Throughout the trail, spruce, Douglas fir and aspen stands shade the pathway. Interspersed with the trees are open grassy meadows. For the first 2 miles, Tewksberry Creek meanders near and occasionally crosses the trail. A few Non-Forest Service System foot and horse trails depart from the main motorized trail. All ATV''s and Motorcycles must stay on the main motorized trail. If you wish to explore these non-system trails, park your ATV or motorcycle a few feet off the trail, and hike them.', 'https://www.fs.usda.gov/recarea/riogrande/recarea/?recid=29208', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '29256', 'West Frisco Trailhead #850', 'trailhead', 37.554970, -106.401102, null, 'Rio Grande National Forest', 'South of Del Norte', 'https://www.fs.usda.gov/recarea/riogrande/recarea/?recid=29256', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '29408', 'Rawley 12 Trailhead', 'trailhead', 38.313038, -106.143363, null, 'Rio Grande National Forest', 'Near Bonanza. Rawley-12 is a reclaimed mining site in the Bonanza Mining District and is a jumping off/exit point for the Mears Toll Road OHV riding trails.', 'https://www.fs.usda.gov/recarea/riogrande/recarea/?recid=29408', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '29486', 'Archuleta Trailhead - Trails # 741 & # 740', 'trailhead', 37.097591, -106.566836, null, 'Rio Grande National Forest', 'The Archuleta trail is composed of 2 segments. Trail 741 is 4.3 miles long. It begins at Forest Road 121 and ends at Forest Trail 740.1. Trail 740.1 is 6.99 miles long. It begins at Trail 740 and ends at the Forest Boundary with the Tierra Amarilla Grant. The trails are open for the following uses: Off Highway Vehicles (OHV) less than or equal to 50 inches wide, motorcycles, snow mobiles, mountain bikes, horseback riding, backpacking, hiking, cross country skiing and snow shoeing.', 'https://www.fs.usda.gov/recarea/riogrande/recarea/?recid=29486', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '29636', 'Valdez Trailhead, Trail 717', 'trailhead', 37.261184, -106.466229, null, 'Rio Grande National Forest', 'The Valdez trailhead is on FDR 250, 1 1/2 miles north of the Pinnacles. Parking space is limited.', 'https://www.fs.usda.gov/recarea/riogrande/recarea/?recid=29636', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '30127', 'Kentuck OHV Trailhead', 'trailhead', 33.530840, -85.853582, null, 'National Forests in Alabama', 'Kentuck OHV Trail has riding for everyone on wheels, whether the vehicle of choice is an ATV, a motorcycle, or a mountain bike. The easy to moderate trail has 4 loops totaling 23 miles. Some of the trails have easy sections with gentle grades, sweeping turns and fairly smooth surfaces with few obstacles. Other trails are more difficult, with steeper grades, tight turns, sections of rough terrain, rocks and log obstacles. Mountain biking opportunities are available.', 'https://www.fs.usda.gov/recarea/alabama/recarea/?recid=30127', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '30276', '234 Trailhead: (936) 344-6205', 'trailhead', 30.527955, -95.563781, null, 'National Forests and Grasslands in Texas', 'This is a trailhead for Multiple Use Trail.', 'https://www.fs.usda.gov/recarea/texas/recarea/?recid=30276', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '30280', '208 OHV Trailhead: (936) 344-6205', 'trailhead', 30.536667, -95.658333, null, 'National Forests and Grasslands in Texas', 'This is a trailhead for Multiple Use Trail.', 'https://www.fs.usda.gov/recarea/texas/recarea/?recid=30280', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '30282', '233 Trailhead: (936) 344-6205', 'trailhead', 30.543611, -95.577778, null, 'National Forests and Grasslands in Texas', 'This is a trailhead for Multiple Use Trail.', 'https://www.fs.usda.gov/recarea/texas/recarea/?recid=30282', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '31214', 'Trailhead: Blue Lake ORV', 'trailhead', 46.396059, -121.731169, null, 'Gifford Pinchot National Forest', 'Provides Off-Highway Vehicle access to : Blue Lake Ridge Trail #271 and Valley Trail #270 which provide a loop options in the Blue Lake Area using connecting trails Bishop Ridge Trail #272 and Jumpoff Trail #271A .', 'https://www.fs.usda.gov/recarea/giffordpinchot/recarea/?recid=31214', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '32184', 'Main Draw OHV Area', 'ohv_area', 40.902472, -104.625787, null, 'Arapaho & Roosevelt National Forests Pawnee NG', 'The Main Draw Off-Highway Vehicle (OHV) area is the only location on the Pawnee National Grassland where non-licensed vehicles are permitted. The area, usually open November 1 through April 9, is in the northwest corner of the Grassland, only a few miles from the Wyoming border. This two-mile long draw or gully is popular with dirt bike riders and others with vehicles under 50 inches wide and must have a spark arrester. Vehicles are required to stay within the draw, and not ride on roads or across the prairie. The OHV must be registered with Colorado Parks & Wildlife.', 'https://www.fs.usda.gov/recarea/arp/recarea/?recid=32184', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '34068', 'Allen Basin Trailhead', 'trailhead', 40.167067, -107.058239, null, 'Medicine Bow-Routt NFs and Thunder Basin NG', 'This Trailhead serves as the access point for the Allen Basin Trail No. 1181. This 1.0 mile ATV trail gives access to Allen Basin Reservoir and multiple dispersed camping sites. More camping opportunities and toilets can be found nearby at Crosho Lake Recreation Area . Please Note : This trail is closed to all vehicles over 50', 'https://www.fs.usda.gov/recarea/mbr/recarea/?recid=34068', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '34107', 'West Fish Creek Trailhead', 'trailhead', 40.217900, -107.152510, null, 'Medicine Bow-Routt NFs and Thunder Basin NG', 'This seasonal trail is generally not melted off until late June/early July due to snow levels at this elevation. This Trailhead primarily serves as the access point for the West Fish Creek ATV Trail No. 1098. This 6.75 mile trail travels through the open parks and Aspen of the Dunckley Flat Tops utilizing an old logging road. Many dispersed camping sites exist along the trail and serve as a popular destination for big game hunters. At 3.9 miles the West Fish Creek Foot/Horse Trail splits off to the right. This trail concludes at the junction of the Gill Reservoir Trail No. 1104 and the N.…', 'https://www.fs.usda.gov/recarea/mbr/recarea/?recid=34107', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '34156', 'Bee Canyon OHV Road 5S07', 'trail_system', 33.743616, -116.836942, null, 'San Bernardino National Forest', '4.1 mile BEE Canyon OHV Road runs from just north of SR 74 (east of Cranston Fire Station) to the junction with San Jacinto Ridge OHV Road 5S09 routes open to all vehicles. Vehicle registration or green/red sticker required for Off Highway Vehicles. Maps of OHV routes are avaliable at the Idyllwild Ranger Station', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=34156', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '34157', 'Indian Canyon OHV Road 4S06', 'trail_system', 33.808954, -116.829418, null, 'San Bernardino National Forest', 'OHV routes open to all vehicles. Vehicle registration or green/red sticker required.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=34157', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '34158', 'Red Mountain OHV Road 6S22', 'trail_system', 33.597591, -116.782247, null, 'San Bernardino National Forest', 'OHV Road 6S22 is 6 miles long, runs from Tripp Flats Road to the Red Mountain Fire Lookout. Current Vehicle registration or green/red sticker required and operating spark arrester.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=34158', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '35555', 'Bulldog Canyon OHV Permit Zone', 'trail_system', 33.550587, -111.573420, null, 'Tonto National Forest', 'Located in the Mesa Ranger District about one hour from Phoenix, Bulldog Canyon is 34,000 acres in size and provides approximately 20 miles of open routes. Bulldog Canyon routes are all full size vehicle width and provide access to the beautiful Sonoran desert and Goldfield Mountains. There are five access points: Blue Point, Usery, Wolverine, Hackamore, and Dutchman. A Tonto OHV Permit is currently required for this area, available at Recreation.gov . Please remember to stay on the routes. Driving off-road is prohibited on the Tonto National Forest. Permits are not available at the District…', 'https://www.fs.usda.gov/recarea/tonto/recarea/?recid=35555', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '38738', 'ODOT Pit Play Area', 'ohv_area', 43.875375, -120.896465, null, 'Ochoco National Forest', 'The ODOT Pit is managed by Central Oregon Combined OHV Operations for the Prineville District of the BLM. The ODOT pit is considered one of the best play area in the state of Oregon. It provides challenges for riders at all levels of experience. The gravel mounds provide excellent jumping opportunities. There are flats around the perimeter of the pit. The ODOT pit has ample parking space for vehicles towing trailers and camping. A kiosk keeps riders informed of regulations and closures as well as providing maps of nearby OHV trail systems. The site also serves as a staging area for access to…', 'https://www.fs.usda.gov/recarea/ochoco/recarea/?recid=38738', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '39148', 'Henderson Flat Staging Area', 'trailhead', 44.431798, -121.143570, null, 'Ochoco National Forest', 'This trailhead provides access to the entire Henderson Flat OHV Trail System . The trailhead is easy to access and has a large parking area that can accommodate vehicles of every size. There are no water services here and no garbage services either, so please be a considerate visitor and pack out what you use. View a vicinity map here .', 'https://www.fs.usda.gov/recarea/ochoco/recarea/?recid=39148', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '39278', 'Camp II OHV Staging Area', 'trailhead', 43.768180, -121.048050, null, 'Deschutes National Forest', 'Provides camping and parking for access to the : East Fort Rock OHV Trail System Area There are picnic tables and fire rings scattered throughout the trees within the staging area providing more a dispersed camp atmosphere. A vault toilet is located near the parking area. There is a learners'' loop adjacent to the staging area. An information Kiosk with trail maps is available. Camp II Staging Area is operated and maintained for your enjoyment by Central Oregon Combined OHV Operations (a Forest Service, & Bureau of Land Management Cooperative agreement), in partnership with Oregon Department…', 'https://www.fs.usda.gov/recarea/deschutes/recarea/?recid=39278', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '39286', 'Ground Hog Rock Crawl and OHV Play Area', 'ohv_area', 43.724580, -120.995800, null, 'Deschutes National Forest', 'A cooperative agreement between Central Oregon''s Combined Off Highway Vehicle Operations (COHVOPS) and the Deschutes County 4-Wheelers of Bend Oregon made this play area a reality in 2006. Complete with a rock crawling pit and large gravel mounds which are remnants of the old rock quarry; this play area has something for every OHV enthusiast. In addition to all this, Groundhog also makes for a convenient staging area for accessing 318 miles of trails on the East Fort Rock OHV Trail System . The pit and play area is open to all classes of vehicles, the trail system is open to Class I (Quads,…', 'https://www.fs.usda.gov/recarea/deschutes/recarea/?recid=39286', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '39290', 'Road 25 OHV Staging Area', 'trailhead', 43.780120, -120.996550, null, 'Deschutes National Forest', 'Provides parking and camping for access to the: East Fort Rock OHV Trail System This staging area is centrally located and the most easily accessed via pavement. It is a popular site for large groups to gather and accomodates large RVs and trailers. There are picnic tables and fire rings scattered throughout the trees, a kiosk with trail maps and visitor information, and a vault toilet within the staging area. No garbage service, Please PACK IT OUT. Road 25 Staging area is operated and maintained for your enjoyment by Central Oregon Combined OHV Operations (a Forest Service, & Bureau of Land…', 'https://www.fs.usda.gov/recarea/deschutes/recarea/?recid=39290', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '39292', 'Road 2510 OHV Staging Area', 'trailhead', 43.780110, -120.996550, null, 'Deschutes National Forest', 'Road 2510 Staging provides parking and camping for access to the: East Fort Rock OHV Trail System Campsites are located in the trees along with a vault toilet, picnic tables and fire rings. There is a large open area adjacent to the trees that is used for parking to host races and other events. There is a learners loop near the staging area and a kiosk with trail maps and visitor information is located at the entrance. Road 2510 Staging area is operated and maintained for your enjoyment by Central Oregon Combined OHV Operations (a Forest Service, & Bureau of Land Management Cooperative…', 'https://www.fs.usda.gov/recarea/deschutes/recarea/?recid=39292', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '39298', 'South Lava OHV Staging Area', 'trailhead', 43.605733, -121.083970, null, 'Deschutes National Forest', 'Provides access to: East Fort Rock OHV Trail system. South Lava OHV Staging area is located on the south end of the East Fort Rock OHV Trail system. This staging area is more remote than the staging areas on the north end of the trail system and provides access to several of the more difficult rated trails in a less populated area. The Ice Rock Quarry Play area is also easily accessed from the staging area. The area will accommodate small groups, RVs and trailers. Vehicular access is via the Finley Butte Road (Road 22) from LaPine and then approximately 2 miles of red cinder surfaced road…', 'https://www.fs.usda.gov/recarea/deschutes/recarea/?recid=39298', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '40625', 'Coal Creek #2214', 'trail_system', 40.119842, -107.695411, null, 'White River National Forest', 'The Coal Creek trail is 4.1 miles long. It begins at Forest Road #262 and ends at the Columbine Trail, #2265. As the trail drops in to Coal Creek, it becomes very steep and narrow with few places to pass oncoming traffic.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=40625', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '40657', 'Georgia Pass Road (South Fork Swan) TH #355', 'trailhead', 39.457941, -105.916596, null, 'White River National Forest', 'This 4WD road passes the town site of Parkville, the main mining camp in Summit County during the gold rush of the 1860s. All that remains now of the once bustling town is the cemetery, which can be accessed via a short hike. From Parkville to the summit, stay on the main road because a number of the intersecting roads are dead-ends. The summit is an open, grassy saddle with spectacular views of Mt. Guyot to the west. The road continues over Georgia Pass on a gravel road into Park County and down to the Michigan Creek Campground, which is located in the South Park Ranger District of the…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=40657', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '40659', 'Indiana Creek Road TH #593', 'trailhead', 39.424860, -105.981821, null, 'White River National Forest', 'Indiana Creek Road leads you up the drainage and eventually connect to Boreas Pass Road (County Road 10), which can then take you back toward Breckenridge or over Boreas Pass to Como in Park County. You can also travel to the old mining town of Dyersville and the Warriors Mark Mine. Please be careful around Dyersville and the Warriors Mark Mine. Another popular route involves making a loop from Indiana Creek Road to Pennsylvania Creek Road.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=40659', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '40661', 'Middle Fork Road (Swan River) TH #6', 'trailhead', 39.494833, -105.946906, null, 'White River National Forest', 'The Middle Fork Road climbs up the drainage and passes the Tony Mine and the old mining town of Swandyke. To your left you will be able to see Wise Mountain, elevation 12,052 feet. To your right is Sheep Mountain, elevation 12,495 feet. The Middle Fork Road provides an excellent opportunity to view the alpine environment and eventually takes you up to the Continental Divide. At this point you can connect with other roads in the area.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=40661', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '40663', 'North Fork Road (Swan River) TH #354', 'trailhead', 39.513248, -105.946983, null, 'White River National Forest', 'Approximately 3.3 miles from the beginning of the North Fork Road you will come to the ruins of the old mining camp of Rexford, just past Garibaldi Gulch. The North Fork Road leads you through thick areas of lodgepole pine and several clear cut areas. The road does eventually come to a dead-end so be prepared to turn-around and follow your same route back down.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=40663', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '40665', 'Pennsylvania Creek Road TH #611', 'trailhead', 39.429605, -106.030210, null, 'White River National Forest', 'Pennsylvania Creek Road climbs up the valley and eventually after approximately 2.5 miles you can turn left and drop down to Indiana Creek Rd (FDR 593). At this point you can continue to Boreas Pass Rd (FDR10) or visit the old mining town of Dyersville and Warriors Mark Mine. Another popular route involves making a loop from Pennsylvania Creek Road to Indiana Creek Road.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=40665', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '40969', 'Deer Creek Road TH #5', 'trailhead', 39.562558, -105.860908, null, 'White River National Forest', 'The Montezuma area was discovered by miners and settled during the silver boom in 1863. The first part of Deer Creek Road is on a gentle incline that takes you through a broad valley. From this point on the road becomes steep and the valley narrows. Eventually the road leads you up to the Continental Divide with opportunities to connect to the Swan Drainage, Saints John or Radical Hill (technical 4WD road).', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=40969', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41019', 'Columbine #2265', 'trail_system', 40.101422, -107.657597, null, 'White River National Forest', 'The Columbine Trail begins at the end of Forest Road 265 and ends at the Forest Boundary/private land. Portions of the trail can be narrow for UTVs: caution is advised.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41019', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41027', 'East Beaver / Sleepy Cat Road #250', 'trail_system', 40.115151, -107.555277, null, 'White River National Forest', 'The East Beaver / Sleepy Cat Road is open to multiple activities. It is mainly used by 4WD vehicles and OHVs, but it is also open to motorcycles, bicycles, hiking and horseback riding. When the East Beaver / Sleepy Cat Road is dry, it is passable with a 2WD vehicle. Timber cutting may be in progress along the road; please watch for logging vehicles. The road passes two privately-owned inholdings; please respect private property and do not open gates to private land. Print a road description and map', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41027', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41031', 'Ellison Mountain #2273', 'trail_system', 40.050289, -107.611141, null, 'White River National Forest', 'The Ellison Mountain Trail is 2.1 miles long. It begins at Forest Road 273 and ends at Forest Road 276.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41031', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41033', 'Buford-New Castle Parallel OHV #2290', 'trail_system', 39.734632, -107.649857, null, 'White River National Forest', 'The Buford-New Castle Parallel OHV Trail begins at the West Elk Trailhead and ends at Forest Road 601 north of Meadow Lake. The trail is 14.5 miles long and is open to motorized vehicles less than 62 inches in width. It is also open to foot, horse, and bicycle travel. Please drive carefully and be courteous to all users. This OHV route leads users across open meadows and through scenic stands of spruce and aspen. The trail also crosses through Lake Park, Seaman Park, and Triangle Park. There are numerous dispersed camping locations along the entire length of the trail. Trail #2290 features…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41033', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41051', 'Marci Camp #2270', 'trail_system', 40.089716, -107.567779, null, 'White River National Forest', 'The Marci Camp Trail begins at Forest Road 270. It heads east until it meets trail #2292, then turns north until it ends at FS290. The east-west section is often muddy with large boulders and requires technical skill to traverse safely. This section is not recommended for beginners. The north-south section is generally fairly dry and easy to travel.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41051', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41053', 'Middle Miller #2201', 'trail_system', 39.851791, -107.782184, null, 'White River National Forest', 'The Middle Miller trail is 3.4 miles long. It begins at Forest Road 218 and ends at Forest Road 217.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41053', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41055', 'Middle Mountain TH #2200', 'trailhead', 39.872536, -107.766524, null, 'White River National Forest', 'The Middle Mountain trail is 5.7 miles long. It begins at Forest Road 218 at the bottom of Miller Creek and ends at Forest Road 217. Shortly after leaving Miller Creek, the trail becomes a narrow catwalk that climbs steadily to the top of the ridge. There are few places to pass along the trail. The terrain below the trail drops precipitously, but there is scrub oak along most of this section which provides some visual security. At the top of the ridge, the trail passes through scrub oak and wild roses, then through aspen and fir until it reaches the meadows on top.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41055', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41067', 'Pagoda #1804', 'trail_system', 40.134044, -107.348439, null, 'White River National Forest', 'The Pagoda Lake Trail trail is 7.3 miles long. It begins at Rio Blanco County Road 8 and ends at Forest Road 230. The trail heads northwest out of the parking area. It mainly follows open parks, with a few short stretches of spruce-fir-dead spruce forest. 3.5 miles from the trailhead, a short spur goes 1/4 mile south to Pagoda Lake. Pagoda Peak (11,120''), named for its unusual pagoda shape, rises to the north. The elevation drops gradually from the trailhead to the Snell Creek Trail junction, one mile beyond Pagoda Lake. The Pagoda Trail continues west around the shoulder of Sand Peak to its…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41067', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41069', 'Pattison Park #2292', 'park', 40.085848, -107.517102, null, 'White River National Forest', 'The Pattison Park trail is 1.4 miles long. It begins at Forest Road 292 and ends at Forest Trail 2270.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41069', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41071', 'Pole Patch #2271', 'trail_system', 40.077522, -107.581272, null, 'White River National Forest', 'The Pole Patch Trail is 2.9 miles long. It begins at Forest Road 250 and ends at Forest Road 285.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41071', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41081', 'Sawmill Mountain #2266', 'trail_system', 40.072886, -107.632262, null, 'White River National Forest', 'The Sawmill Mountain Trail is 2.1 miles long. It begins at Forest Road 260 and ends at Big Beaver Creek. This trail is steep and narrow with multiple switchbacks, and no room for vehicles to pass each other until the bottom.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41081', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41085', 'Sterry Lake #2240', 'trail_system', 39.929370, -107.612062, null, 'White River National Forest', 'The Sterry Lake Trail is 1.6 miles long. It begins at Forest Road 240 and ends where the (non-motorized) Burro Mountain Trail #1833 begins.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41085', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41087', 'Stove Gulch #2278', 'trail_system', 40.109921, -107.647070, null, 'White River National Forest', 'The Stove Gulch Trail is 2.0 miles long. It begins at Forest Road 260 and ends at Forest Road 250. When this trail is wet, it is best avoided; when it is dry, it is a good trail for family outings and beginners. The Stove Gulch Trail offers scenic views of Hay Park and Ellison Mountain, with overlooks of Stove Gulch, Allen Creek and Big Beaver Basin.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41087', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41093', 'TI Cutoff #2217', 'trail_system', 39.807004, -107.838558, null, 'White River National Forest', 'The TI Cutoff Trail is 3.1 miles long. It begins at Forest Road #221 near the TI Cow Camp and ends at Forest Road #217. This trail is narrow and very steep in places, with no room for vehicles to pass.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41093', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41109', 'Boiler Creek #1843', 'trail_system', 39.724457, -107.421052, null, 'White River National Forest', 'The Boiler Creek trail is2.28 miles long. It begins at Forest Road 636 and ends at Forest Boundary. The trail is open for high clearance vehicles; OHV, horse and foot traffic.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41109', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41111', 'West Elk Trailhead', 'trailhead', 39.731981, -107.648024, null, 'White River National Forest', 'The West Elk Trailhead is a year-round parking area for motorized and non-motorized recreational activities. The trailhead is located along Forest Road 245 (Buford-New Castle Road) approximately 7.5 miles north of the Forest boundary. The parking area has room for several dozen passenger vehicles and trailers. During the summer, the West Elk Trailhead serves as the southern access point for Motorized Trail #2290 (also known as the Buford-New Castle Parallel Trail). During the winter, the trailhead is one of the access points to the Flattops snowmobile trail system, providing parking for…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41111', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41179', 'Battlement Jeep (Forest Road 847)', 'trail_system', 39.395676, -107.933793, null, 'White River National Forest', 'The Battlement Jeep Trail is 4.3 miles long and gains 2,000 feet of elevation. The route is extremely rough, rocky, and steep, and is recommended for experts only. Trail features include steep scree slopes and mud bogs. Scenery along the trail includes open meadows, stands of spruce & aspen, and wildlife viewing opportunities. The trail is open to motorized and non-motorized uses, though motorized access is recommended for OHVs or other high clearance, 4 wheel drive vehicles only. The Jeep Trail begins at the Battlement Trailhead and ends at the Battlement Reservoirs. The Battlement…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=41179', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '41960', 'San Gabriel Canyon Off-Highway Vehicle (OHV) Area', 'trail_system', 34.237732, -117.860136, null, 'Angeles National Forest', 'The San Gabriel Canyon Off-Highway Vehicle Area (OHV) (brochure) is located 11 miles north of Azusa, CA, on Highway 39. Over 160 acres of rocky, sandy river bottom await users of 2-, 3-, and 4-wheeled OHVs. Reservations are required through Recreation.gov . MORE INFO: (1) The San Gabriel Canyon OHV Area is open on Saturdays and Sundays from 8 a.m.-4 p.m. All vehicles must exit the area by 4:30 p.m. (2) Reservations are required before entering the OHV area. Please visit Recreation.gov to buy your tickets prior to entering San Gabriel Canyon. There are two different types of tickets…', 'https://www.fs.usda.gov/recarea/angeles/recarea/?recid=41960', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42473', 'Spinreel Sand Camping', 'trail_system', 43.569880, -124.205505, null, 'Siuslaw National Forest', 'Spinreel Sand Camp sites are located directly on the sand in the heart of the Oregon Dunes National Recreation Area. Access to campsites is only by 4x4 vehicles via soft sand routes. Individual sites are identified by numbered posts. Each site accommodates up to five vehicles and 20 campers for tent camping. Spinreel OHV Staging Area is the access point for the sand camping sites #58 to 73. Saunders Lake OHV Trail , off Crannog Road is an alternative access point for these sites. Sites are rustic and no toilets or campfire pits are available. Portable toilets and fire pans are highly…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42473', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42477', 'Goosepasture OHV Staging Area', 'trailhead', 43.954974, -124.130503, null, 'Siuslaw National Forest', 'Located less than a mile from Florence, OR, this popular OHV staging area can be accessed from South Jetty Road. This large paved parking area can accomodate longer trailers, but can often be full by mid-morning during the busy summer season and sunny weather weekends. OHV riders have access to large open sand dunes, designated OHV trails through vegetated areas as well as the beach. Goosepasture Staging also provides access to South Jetty Sand Camping sites. A noise buffer OHV closure is in place on the eastern boundary of the riding area due to proximity to nearby residential areas and…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42477', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42503', 'South Jetty OHV Staging Area', 'trailhead', 43.956850, -124.119200, null, 'Siuslaw National Forest', 'South Jetty OHV Staging Area provides a large paved parking area for off-highway vehicle day use staging, with access to South Jetty OHV Trail and open riding opportunities in the South Jetty dunes.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42503', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42507', 'South Jetty Sand Camping', 'trail_system', 43.955485, -124.130851, null, 'Siuslaw National Forest', 'South Jetty sand camping sites are located directly on the sand, dispersed along the coast and the Siltcoos River and must be accessed by 4X4 vehicles only. Standard sites accommodate up to 20 people and five vehicles. Two group sites accommodate up to 40 people and 10 vehicles. Goosepasture OHV Staging Area is the access point for sand camping sites 1 to 14. No water is available so campers should bring an ample amount. Campsites are primitive and it''s recommended that all campers bring portable toilets and fire pans. Campsites are available year-round and reservations may fill up quickly in…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42507', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42527', 'Driftwood II Campground', 'trail_system', 43.881059, -124.148043, null, 'Siuslaw National Forest', 'Surrounded by shore pine, waxmyrtle, huckleberry and salal, Driftwood is a designated off-road vehicle riding campground that offers direct sand access to the Oregon Dunes National Recreation Area. The layout of the campground is a large parking lot with designated camping sites. Most sites come with a picnic table and campfire pit, but RV pull-through sites 49-58 do not have these amenities. The campground has flush toilets, drinking water and hot showers. Off-road vehicle riding is the ultimate attraction here and the Driftwood II OHV Trail is a great place to start. For added variety,…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42527', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42539', 'Siltcoos Beach Day Use OHV Staging', 'trailhead', 43.882652, -124.153395, null, 'Siuslaw National Forest', 'Siltcoos Beach Day Use and OHV Staging Area provides paved parking for direct pedestrian beach access, as well as off-highway vehicle (OHV) staging and access to the beach (via Coast Guard North OHV Trail ) and open riding opportunities in the Siltcoos area.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42539', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42547', 'Siltcoos Sand Camping', 'trail_system', 43.881080, -124.149508, null, 'Siuslaw National Forest', 'Siltcoos Sand Camping sites are located directly on the sand, dispersed along the coast and the Siltcoos River. Siltcoos'' year-round campsites must be accessed by 4X4 vehicles only. Driftwood II OHV Trail is the access point for the sand camping sites 15 to 26. Sites 27 to 30 can be accessed by Incinerator OHV Trail . Standard sites accommodate up to 20 people and five vehicles. Two group sites accommodate up to 40 people and 10 vehicles. The campground is primitive and provides no water, restrooms or campfire rings. Visitors must bring their own water, portable toilets and fire pans. This is…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42547', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42609', 'Umpqua Beach #3 Day Use /OHV Staging Area', 'trailhead', 43.632620, -124.210600, null, 'Siuslaw National Forest', 'Located south of Winchester Bay, OR, this area is home to the tallest sand dunes in the Oregon Dunes National Recreation Area. Umpqua Beach #3 Day Use and OHV Staging Area provides parking and access for pedestrian beach access as well as off-highway vehicle (OHV) staging for open sand riding opportunities in the Umpqua dunes. A ride to the top of a tall dune offers spectacular views of the Pacific Ocean. The beach provides miles of walking and is closed to OHV travel year-round.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42609', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42611', 'Umpqua Beach #2 Day Use /OHV Staging Area', 'trailhead', 43.648080, -124.207700, null, 'Siuslaw National Forest', 'Located south of Winchester Bay, OR, this area is home to the tallest sand dunes in the Oregon Dunes National Recreation Area. Umpqua Beach #2 Day Use and OHV Staging Area provides parking and access for pedestrian beach access as well as off-highway vehicle (OHV) staging for open sand riding opportunities in the Umpqua dunes. A ride to the top of a tall dune offers spectacular views of the Pacific Ocean. The beach provides miles of walking and is closed to OHV travel year-round.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42611', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42615', 'Umpqua Sand Camping', 'trail_system', 43.631550, -124.211784, null, 'Siuslaw National Forest', 'Umpqua Sand Camp sites are dispersed along a sandy beach on the Pacific Coast. All sites can only be accessed by 4X4 vehicles. No water is available so campers should bring an ample amount. Campsites are primitive and it''s recommended that all campers bring portable toilets and fire pans. Standard sites fit five vehicles and up to 20 people. The two group campsites fit 10 vehicles and 40 campers. Umpqua Beach #2 Day Use & OHV Staging is the access point for sand camping sites 31 to 40. Umpqua Beach #3 Day Use & OHV Staging is the access point for sand camping sites 41 to 57. Campers with…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42615', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42623', 'Hauser Sand Camping', 'trail_system', 43.489266, -124.226919, null, 'Siuslaw National Forest', 'Hauser offers a selection of dispersed campsites in the Oregon Dunes National Recreation Area. Standard sites fit five vehicles and up to 20 people. The two group campsites fit 10 vehicles and 40 campers. Note that all sites can only be accessed by 4X4 vehicles. Campsites are available year-round and reservations may fill up quickly in peak summer season. No water is available so campers should bring an ample amount. Campsites are primitive and it''s recommended that all campers bring portable toilets and fire pans. Sandy Way off Hauser Depot Road is the access point for the sand camping sites…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42623', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42625', 'Horsfall Beach Campground', 'trail_system', 43.453666, -124.276294, null, 'Siuslaw National Forest', 'Horsfall Beach Campground is ideal for off-road vehicle riders or for visitors looking to take it easy on the beach. Flush toilets, drinking water, a picnic area and an accessible beach viewing platform are available at this 34-site campground. The day-use area provides a paved parking area for pedestrian beach access. The self-pay station for this area is located on Horsfall Beach Road. There are no RV dump stations or RV hookups. The main activity is OHV riding on the dunes. Horsfall Beach Day Use OHV Staging Area is located here, and provides access to off-highway adventures in the Bull…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42625', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42627', 'Horsfall Beach Day Use OHV Staging', 'trailhead', 43.453666, -124.276294, null, 'Siuslaw National Forest', 'Horsfall Beach Day Use is at the westernmost portion of the parking area, which is shared with Horsfall Beach Campground . This paved parking area gives access to: Beach hiking at the western end of Horsfall Beach Road OHV staging acccess to Coast Guard South OHV Trail leading to open riding areas. A wheel-chair accessible beach viewing platform.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42627', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42629', 'Horsfall Campground', 'trail_system', 43.441305, -124.245840, null, 'Siuslaw National Forest', 'Horsfall Campground, tucked in the Oregon Dunes National Recreation Area , provides access to miles and miles of dunes, beckoning off-road vehicle riding enthusiasts. Perks include flush toilets, drinking water and token operated showers. An ATV loading ramp is also available. Picnic tables and fire rings are at each campsite. The number one activity is off-roading on the dunes. OHV trails and open riding zones are northwest of the campground. Sand trails are accessible from the campground. See details at Horsfall OHV Staging Area .', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42629', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42631', 'Horsfall Day Use OHV Staging', 'trailhead', 43.443050, -124.245240, null, 'Siuslaw National Forest', 'Horsfall Day Use OHV Staging Area provides a paved parking area for off-highway vehicle (OHV) day use parking and access to open riding opportunities in the Horsfall riding area.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42631', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42633', 'Horsfall Sand Camping', 'trail_system', 43.442762, -124.245213, null, 'Siuslaw National Forest', 'Horsfall Sand Camping dispersed camping area is on the sand in the southern edge of the Oregon Dunes National Recreation Area. Access to campsites is by 4x4 vehicles only via soft sand routes. Sites are rustic and no toilets or campfire pits are available. Portable toilets and fire pans are highly recommended. Individual sites are identified by numbered posts. Each site accommodates up to 5 vehicles and 20 campers for tent camping. Three group sites accommodate 40 people and 10 vehicles. Horsfall Beach Road is the access point for sand camping sites #98 to 138. Bull Run Staging area is the…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42633', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42635', 'Old Bark Road OHV Staging Area', 'trailhead', 43.446065, -124.245844, null, 'Siuslaw National Forest', 'Old Bark Road OHV Staging Area provides paved parking for OHV staging, access to Bark Road OHV Trail and open riding opportunities in the Horsfall riding area. The staging area also provides access to dispersed sand camping sites located around the facility and beyond.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42635', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42651', 'Bull Run OHV Staging Area', 'trailhead', 43.452452, -124.268847, null, 'Siuslaw National Forest', 'Bull Run OHV Staging Area provides paved parking for OHV staging, quick access to the beach via Bull Run OHV Trail and open riding opportunities to the north. The staging area also provides access to dispersed sand camping sites 126 through 138. One vault toilet and several picnic tables are available to visitors.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42651', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42653', 'Spinreel Campground', 'trail_system', 43.569730, -124.203877, null, 'Siuslaw National Forest', 'Spinreel Campground is an off-road vehicle rider''s dream, located in the Oregon Dunes National Recreation Area along Tenmile Creek in Coos County with prime access to the expansive off-road trails along the sandy dunes. Drinking water, flush toilets, campfire rings, a picnic area and boat ramp are available for campers. The ramp is designed for small boats entering Tenmile Creek. There are no electric hookups or dump stations in this campground. Thrill-seekers have their choice of riding on designated routes including Coast Guard North and Coast Guard South Trails and 430 OHV Trail . OHV…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42653', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42657', 'Spinreel OHV Staging Area', 'trailhead', 43.570310, -124.205580, null, 'Siuslaw National Forest', 'Located 12 miles north of North Bend, OR, Spinreel OHV Staging Area provides paved parking and off-highway vehicle staging for those wishing to access the beach via Ten Mile OHV Trail and open riding opportunities in the Spinreel dunes and beyond.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42657', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42691', 'Derrick Road Dispersed Camping Area', 'trail_system', 45.317030, -123.943400, null, 'Siuslaw National Forest', 'Dispersed camping and day use area with access to the northern end of Sand Lake Recreation Area OHV area. Sites offer vault toilets and fire rings. No water available.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42691', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42693', 'East Dunes Campground', 'trail_system', 45.287121, -123.955960, null, 'Siuslaw National Forest', 'The 59 site East Dunes Campground is in the popular Sand Lake OHV area. The campground has dune and beach access. Some sites have fire rings.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42693', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42697', 'West Winds Day Use OHV Staging', 'trailhead', 45.287954, -123.957893, null, 'Siuslaw National Forest', 'Access to the southern end of Sand Lake Recreation Area OHV area.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42697', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42699', 'Sandbeach Campground', 'trail_system', 45.284635, -123.956741, null, 'Siuslaw National Forest', 'Sandbeach Campground is ideal for off-road vehicle lovers with year-round access to nearly 1,100 acres of coastal sand dunes. The 81 site campground is part of the Sand Lake Recreation Area and home to the dune playground. Parking aprons are paved. Campground amenities include drinking water, flush toilets, campfire rings and an off-road vehicle loading ramp. Off-road vehicle riding is the primary attraction for campers. The nearby Sand Lake Estuary offers fishing, swimming, crabbing, kayaking, hiking and wildlife viewing. The near-natural state of the 900-acre estuary provides a home to many…', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42699', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42701', 'West Winds Campground', 'trail_system', 45.286889, -123.957803, null, 'Siuslaw National Forest', 'This 18 site campground adjacent to large sand dune area at Sand Lake is a popular OHV campground with dune and beach access. Campsites are paved, some with fire rings, those without fire rings must have raised fire pits.', 'https://www.fs.usda.gov/recarea/siuslaw/recarea/?recid=42701', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '42878', 'East Fork Road Information Station', 'trail_system', 37.376400, -106.890800, null, 'San Juan National Forest', 'East Fork Road Information Station', 'https://www.fs.usda.gov/recarea/sanjuan/recarea/?recid=42878', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '43435', 'Brock Creek', 'trail_system', 35.508367, -92.819350, null, 'Ozark-St. Francis National Forests', 'The Brock Creek Trail is a multi-use trail system located on the Big Piney Ranger District in the beautiful Ozark National Forest. The trail system consists of two major loops and many interconnecting loops. The combined loops provide over 42 miles of trails for dirt bikers, Off-Highway Vehicle (OHV) riders, and horseback riders. The trails meander through majestic oak/hickory forests and occasional areas of pine. These areas also contain small streams that traverse through the trail system, adding to the beauty of the area. The Brock Creek Trail system offers riders of all skill levels a…', 'https://www.fs.usda.gov/recarea/osfnf/recarea/?recid=43435', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '43461', 'Mill Creek', 'trail_system', 35.763148, -93.861222, null, 'Ozark-St. Francis National Forests', 'Mill Creek Trail leads the rider through remote areas of the Ozark National Forest and features spectacular mountainous terrain, scenic views, lush upland hardwood forests, unique rock outcrops and clear mountain streams. The main trail and inside loops are connected to accommodate riders who want to vary the length of their trips. The Trail is gravel or unsurfaced and is made of rough and rocky terrain. The difficulty varies from easy to very difficult. Campground and Day-Use Area Rules OHV Trail Map', 'https://www.fs.usda.gov/recarea/osfnf/recarea/?recid=43461', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '47404', 'Bear Valley Trailhead', 'trailhead', 32.816667, -116.531944, null, 'Cleveland National Forest', 'Bear Valley Trailhead When area is closed due to wet weather vehicles less than 53 inches wide can still access the trails. USFS approved Spark Arresters are required year round. Green sticker riding season is year round. Red sticker riding season is October 1 - April 30. (This also applies to OHVs that are registered out of state.) Pets Allowed Yes Fees Federal Recreational Lands Pass/ Adventure Pass Required Hike/Ride Time Full day Difficulty Easy to Moderate Best Seasons Fall, Spring, Winter Location Off I-8 at Pine Valley Road Ranger District Descanso Ranger District - (619) 445-6235 Bear…', 'https://www.fs.usda.gov/recarea/cleveland/recarea/?recid=47404', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '47408', 'Bobcat Meadow Campground', 'trail_system', 32.712500, -116.556389, null, 'Cleveland National Forest', 'Bobcat Meadow Campground USFS approved Spark Arresters are required year round. Green sticker riding season is year round. Red sticker riding season is October 1 - April 30. (This also applies to OHVs that are registered out of state.) Trails n/a Campfires Campfires are not allowed when elevated fire restrictions are in effect. Please see our current fire restrictions page for more details. Fees Federal Recreational Lands Pass/ Adventure Pass Required (NO CASH accepted) Hike/Ride Time n/a Difficulty n/a Best Seasons Year Round Location Off the I-8 at Buckman Springs Rd towards Four Corners…', 'https://www.fs.usda.gov/recarea/cleveland/recarea/?recid=47408', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '47428', 'Corral Canyon Campground', 'trail_system', 32.711389, -116.572500, null, 'Cleveland National Forest', 'Corral Canyon Campground USFS approved Spark Arresters are required year round. Green sticker riding season is year round. Red sticker riding season is October 1 - April 30. (This also applies to OHVs that are registered out of state.) Distance n/a Campfires Campfires are not allowed when elevated fire restrictions are in effect. Please see our current fire restrictions page for more details. Fees Federal Recreational Lands Pass/ Adventure Pass Required (NO CASH accepted) Hike/Ride Time n/a Difficulty n/a Best Seasons Spring, Winter Location Off the I-8 at Buckman Springs Rd. Turn right on…', 'https://www.fs.usda.gov/recarea/cleveland/recarea/?recid=47428', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '47450', 'Four Corners Trailhead', 'trailhead', 32.724444, -116.558333, null, 'Cleveland National Forest', 'Four Corners Trailhead When area is closed due to wet weather vehicles less than 53 inches wide can still access the trails. Distance 50 miles of connecting trails Pets Allowed Yes Fees Federal Recreational Lands Pass/ Adventure Pass Required Hike/Ride Time Full day Difficulty Easy to Strenuous - dependent on connection Best Seasons Year Round Location Off I-8 at Buckman Springs Rd. Ranger District Descanso Ranger District - (619) 445-6235 Located at the end of Morena Stokes Valley Rd, Four Corners trailhead connects visitors to over 50 miles of off-road trails. The staging area is the…', 'https://www.fs.usda.gov/recarea/cleveland/recarea/?recid=47450', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '52133', 'Umapine OHV Trailhead', 'trailhead', 45.113839, -118.562381, null, 'Wallowa Whitman National Forest', 'The Umapine OHV Trailhead sits adjacent to the Umapine Campground . Located in a scenic ponderosa pine forest west of Vey Meadows between Cuuyem and Umapine Creeks, the trailhead serves as a central staging area for the Winom-Frazier OHV trail area which gives off-road riders access to more than 140 miles of challenging trails.', 'https://www.fs.usda.gov/recarea/wallowa-whitman/recarea/?recid=52133', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '52589', 'Oregon OHV Trailhead', 'trailhead', 44.547081, -118.341342, null, 'Wallowa Whitman National Forest', 'The Oregon OHV Trailhead is located along Highway 7 adjacent to the Oregon Campground. The trailhead serves as a midway access area for the Blue Mountain OHV Trail . The recreation area has a parking area, loading ramp, and an accessible vault toilet.', 'https://www.fs.usda.gov/recarea/wallowa-whitman/recarea/?recid=52589', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '53560', 'McCubbins Gulch Picnic Site', 'trail_system', 45.129474, -121.567403, null, 'Mt. Hood National Forest', 'This picnic area is within the McCubbins Gulch OHV Area . A few picnic tables are available as well as a vault toilet in the adjacent campground . Parking for 8 single vehicles. McCubbins Gulch OHV Riding Area, located approximately 50 miles southeast of Portland out Hwy 26 south to Hwy 216 east to Forest Service Road 2110, was first established back in the early 1960s as a favorite place for dirt bikers coming out of the Portland area. Although originally designed and laid out with dirt bikes (single-track, Class 3) in mind, many of the established trails have been opened up to Class 1 ATVs…', 'https://www.fs.usda.gov/recarea/mthood/recarea/?recid=53560', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '55788', 'Sugar Pine Staging Area', 'trailhead', 39.124167, -120.760556, null, 'Tahoe National Forest', 'During the winter months, the American River OHV system may be closed after periods of heavy rain when soil moisture levels would likely result in trail damage if riding were to occur. For the most up to date information, please call (530)-478-6254 x228 This is the main staging area for the Foresthill OHV Trails. The large gravel parking lot area is the best location for day users to park and for RV or toy hauler camping (camping subject to closure per forest order). There are no hookups or water. There are vault toilet restrooms and trash containers centrally located. Loading ramps are…', 'https://www.fs.usda.gov/recarea/tahoe/recarea/?recid=55788', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '55790', 'China Wall Staging Area - (530)-478-6254 x228', 'trailhead', 39.151389, -120.676944, null, 'Tahoe National Forest', 'During the winter months, the American River OHV system may be closed after periods of heavy rain when soil moisture levels would likely result in trail damage if riding were to occur. For the most up to date information, please call (530)-478-6254 x228 China Wall is used as a staging area in summer by 2-wheeled OHV dirt bikes and motorcycles. The trail is not wide enough to accommodate quad OHV''s. In the winter China Wall is a staging area for snowmobiles, cross-country skiers, and snowshoe users. When there is snow on the ground it is an easy place for kids to play in the snow, but there…', 'https://www.fs.usda.gov/recarea/tahoe/recarea/?recid=55790', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '55800', 'Little Truckee Summit OHV/Snowmobile Staging Area', 'trailhead', 39.504613, -120.283227, null, 'Tahoe National Forest', 'Easy to More Difficult trails depending on length and trail selected. Terrain: Generally comprised of gentle slopes. Use: Heavy snowmobile use. Because of snowmobile use, ski use is not recommended. Use of wheeled vehicles on snowmobile routes is prohibited. Topographic maps: Sierraville, Sattley, Independence Lake and English Mountain', 'https://www.fs.usda.gov/recarea/tahoe/recarea/?recid=55800', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '55806', 'Yuba Pass Snowpark', 'ohv_area', 39.386911, -120.185683, null, 'Tahoe National Forest', 'The Yuba Pass Area offers 100 miles of trail opportunities especially for snowmobilers and nordic skiers. The Sno-Park site on the south side of Hwy 49 at Yuba Pass provides parking and access for cross-country skiing, dog sledding, snowmobiling or just general snow play. Snow conditions determine accessibility and opportunities available at each Sno-Park site. View more information here: https://ohv.parks.ca.gov/?page_id=23049.', 'https://www.fs.usda.gov/recarea/tahoe/recarea/?recid=55806', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '55816', 'Parker Flat Staging Area - (530)-478-6254 x228', 'trailhead', 39.128917, -120.763519, null, 'Tahoe National Forest', 'During the winter months, the American River OHV system may be closed after periods of heavy rain when soil moisture levels would likely result in trail damage if riding were to occur. For the most up to date information, please call (530)-478-6254 x228 Staging area for Foresthill OHV Trails with limited camping available (camping subject to closure per forest order). Beginning fall of 2020, the Sugar Pine Off-Highway Vehicle (OHV) Wet Weather Management Plan will be implemented for OHV Roads and Trails on American River Ranger District. This will increase OHV riding opportunities by adopting…', 'https://www.fs.usda.gov/recarea/tahoe/recarea/?recid=55816', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '56394', 'Prosser Pits OHV Area', 'ohv_area', 39.386911, -120.185683, null, 'Tahoe National Forest', 'Please read information on bulletin board at entrance to Prosser Pits before proceeding into the area. Features : Suitable for motorcycles and OHV use. Difficulty level ranges from easy to difficult. Large open area to ride with additional access to designated trails and roads. All level of riders can find a place to challenge themselves, or relax and take an easy ride. Please respect other riders and be aware on any day there may be a variety of levels of rider experience in the pit. Precautions : This area is very close to private homes. Caution should be exercised. Do not trespass onto…', 'https://www.fs.usda.gov/recarea/tahoe/recarea/?recid=56394', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '59668', 'Trout Trailhead #831', 'trailhead', 37.635607, -106.672539, null, 'Rio Grande National Forest', 'The Trout trail is 10.4 miles long. It begins at Hwy 160 and ends at Forest Road 430. The trail is open for the following uses: Motorcycle Trail Riding, Off Highway Vehicles (OHV) less than or equal to 50 inches wide, Mtn Biking, Foot and Horse Travel.', 'https://www.fs.usda.gov/recarea/riogrande/recarea/?recid=59668', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '6225', 'Monday Creek OHV System', 'trail_system', 39.497834, -82.210170, null, 'Wayne National Forest', 'The Monday Creek area of the Wayne National Forest provides some excellent opportunities for riding off-highway vehicles (OHVs). This trail system, north of Nelsonville, provides approximately 75 miles of designated trails to OHV riders, mountain bikers, and hikers. Loading ramps are available at the New Straitsville and White Oak Trailheads. Trailheads Monday Creek Trailhead Sycamore Trailhead Elm Trailhead Scarlet Trailhead Red Oak Trailhead White Oak Trailhead Long Ridge Trailhead New Straitsville Trailhead', 'https://www.fs.usda.gov/recarea/wayne/recarea/?recid=6225', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '6232', 'Hanging Rock OHV System', 'trail_system', 38.581230, -82.724370, null, 'Wayne National Forest', 'The Hanging Rock area of the Wayne National Forest provides some excellent opportunities for riding off-highway vehicles (OHVs). This system has 26 miles of trail available for off-highway vehicle, mountain bike, and hiking use. These trails wind through an area strip-mined in the 1960''s and 1970''s. Much of the upland area was badly scarred, and some areas are left with steep slopes providing challenging trails to riders. The area is also known for its fishing ponds, 51 of which are available for fishing. The ponds which are scattered along the OHV trail, lend a picturesque backdrop to an OHV…', 'https://www.fs.usda.gov/recarea/wayne/recarea/?recid=6232', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '6233', 'Pine Creek OHV System', 'trail_system', 38.737870, -82.730460, null, 'Wayne National Forest', 'Trail Advisory- Wayne National Forest Supervisor Anthony Scardina has issued a Closure Order for a portion of the Telegraph Trail, located on the Ironton Ranger District in Lawrence County. The order is necessary to prevent unlawful access to private property and to protect national forest property and resources. The order includes a 3.2-mile section of trail located between the Telegraph Trailhead and the intersection of Brushy Fork Road. The Forest Service has determined that the section of trail is on private property and will need to be rerouted. The order does not include the Telegraph…', 'https://www.fs.usda.gov/recarea/wayne/recarea/?recid=6233', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '64170', 'Lake McClellan UTV/ATV Area Trailhead', 'trailhead', 35.210397, -100.879500, null, 'Cibola National Forest and Grasslands', 'The Lake McClellan UTV/ATV Area Trailhead is located outside of the Lake McClellan Campground. This multiple-use trail system is approximately 10 miles in length with a difficulty rating of light to moderate.', 'https://www.fs.usda.gov/recarea/cibola/recarea/?recid=64170', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '66108', 'Bar HL/Hay Flat Trailhead FR #211', 'trailhead', 39.817356, -107.759070, null, 'White River National Forest', 'The Bar HL/Hay Flat road provides good access to a number of OHV trails; some provide loop opportunities and some are dead ends. This road requires a vehicle with clearance. Water bars can fill and become deep. It is not recommended for vehicles pulling long trailers, and vehicles pulling short trailers should consider road conditions. There are few places to turn around in the first few miles of the road. The road climbs through a forested area, then opens to a meadow as it reaches Hay Flats.Vegetation includes spruce, fir, and aspen, with scrub oak at lower elevations.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=66108', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '66109', 'Deadhorse-Long Park Loop FR#230', 'park', 40.065521, -107.407065, null, 'White River National Forest', 'From the west entrance, the road follows a series of switchbacks up a south facing slope. Near the top, the road offers a nice view of the valley and the North Fork of the White River below. After approximately 2 miles, the road enters Long Park. It then splits with the west fork following Long Park Creek and ending at Trough Gulch. The north fork proceeds up Long Park Creek to the divide between the Williams Fork and White River drainages. As you follow the divide to the north, you see the Elk Head Mountains and the south fork of the Williams Fork River below. To the east and south, you see…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=66109', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '66111', 'Four Mile FR#214 / Widow Springs FR#212', 'trail_system', 39.871139, -107.757840, null, 'White River National Forest', 'The Four Mile Road rises out of Miller Creek and follows Four Mile Creek through scrub oak and stands of spruce and fir. After one mile, the road levels off on a rolling plateau. The road travels through open parks, aspen stands and scattered patches of conifers for the remaining 4 miles to the junction of the Bar HL Road (FR#211). The Widow Springs Road traverses the area to the east of the Four Mile Road, and meets the Bar HL Road after 8.5 miles. At their southern ends, both roads join the Bar HL Road. It is possible to complete a loop by traveling 2 miles on the Bar HL Road. Print a road…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=66111', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '66112', 'Moeller Creek FR#290 (via Fawn Creek FR #280)', 'trail_system', 40.061510, -107.530956, null, 'White River National Forest', 'The Moeller Creek Road travels through scattered stands of conifers, open parks and aspen. Two short side roads diverge from the Moeller Creek Road. The Log Springs Road begins roughly 2 miles up the Moeller Creek Road and heads southeast 1 mile to Log Springs. Another mile up the Moeller Creek Road, the Pattison Park Road drops down a small drainage for 1 mile into Pattison Park. Past the Pattison Park Road about 1/2 mile, the road emerges into Little Lost Park. It crosses the 160 acre grassy meadow and continues 1/4 mile to a junction with FR#293, which forks northeast to Lost Park. For the…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=66112', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '66115', 'Long Park #1809', 'park', 40.052651, -107.461000, null, 'White River National Forest', 'The Long Park Trail connects to the Deadhorse-Long Park loop, Forest Road #230. It also connects with Lost Park Forest Road #231, which is also open to motorcycles and ATVs from 6/21-8/31 only. From the trailhead, the trail climbs rapidly for 1/2 mile to the northeast where it reaches the crest of the ridge between the White River and Long Park Creek drainages. The trail travels through scrub oak and aspen for 1.2 miles, providing nice views of the surrounding area. It follows Long Park Creek for the next 1.6 miles into the meadows of Long Park, where it joins Forest Road #230 and Forest Road…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=66115', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '67227', 'Alto Pit OHV Day Use/Campground', 'trail_system', 34.590014, -112.559109, null, 'Prescott National Forest', 'ATV and dirt bike riders (off-road vehicles of 50 or less in width) enjoy 400 acres with approximately 20 miles of motorized trails, 2 cross-country areas, and a designated children''s area. The main area is a former gravel pit at 6,200 foot elevation just below Granite Mountain. There is also a smaller gravel pit. Rock and granite surface the area. A host is available to provide information and assist visitors. View photos on Flickr Note: This site closes following especially heavy rain or snow, and when the roads are too icy. If you plan to visit and want to make sure it is open, please…', 'https://www.fs.usda.gov/recarea/prescott/recarea/?recid=67227', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '67245', 'Hayfield Draw OHV Day Use Area', 'ohv_area', 34.636386, -111.946545, null, 'Prescott National Forest', 'Approximately 80 acres of motorized trails and cross-country areas for motorcycles and OHVs of less than 50-inches in width. Trails and open pit areas challenge rider skill levels from beginner tot to experienced adult. Please ride in the area most appropriate to your skill level to reduce the risk of accidents. The area where cross-country use is restricted is delineated by orange fiberglass posts. Each skill level area is marked with different colored fiberglass posts. Tot Lot (White Posts) - This area is only for the little riders as they learn the sport. No large machines please. Beginner…', 'https://www.fs.usda.gov/recarea/prescott/recarea/?recid=67245', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '67988', 'Gillette Ridge Motorcycle #131', 'trail_system', 48.711300, -117.806900, null, 'Colville National Forest', 'Gillette Ridge is a multi use trail constructed for single track motorcycles. It has 13.1 miles to offer which includes two connecting loop routes. If you are looking for a longer ride or hike on the mountain, these loop routes will provide you with fun additional excursions. the trail is a moderate to difficult traverse and offers three separate access points. (Rogers Mountain, Clinton Creek and Onion Creek) Rogers Mountain has evidence of an old fire lookout to explore and the view of Aladdin Vally to the East is breathtaking. Recommended season for traversing the trail is late Spring to…', 'https://www.fs.usda.gov/recarea/colville/recarea/?recid=67988', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '68036', 'Rufus Route ORV #148', 'trail_system', 48.617498, -117.535152, null, 'Colville National Forest', 'This multi-purpose trail follows a roadbed. Upper portion of the trial becomes boggy and difficult to cross during wet periods. Wildflowers and wildlife viewing. The trail continues to Granite Peak or Frater Lake on Trail #142. The western portion of the trail west of FS RD 2712 is suitable for 50 inch and under ATVs. East of FS RD 2712 is motocycle road only.', 'https://www.fs.usda.gov/recarea/colville/recarea/?recid=68036', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '70960', 'Bender Creek Trailhead', 'trailhead', 43.528090, -115.869130, null, 'Boise National Forest', 'Bender Creek Trailhead - is a signed site with a restroom, loading/unloading ramp for ATVs, registration box and visitor information. This is one of the trailheads in the Danskin OHV area. The trailhead marks one of the major entrances to the #300 Trails of the Danskin Trail System. I All trailheads have space for parking.', 'https://www.fs.usda.gov/recarea/boise/recarea/?recid=70960', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '70996', 'Cinder Hills Off Highway Vehicle Area', 'ohv_area', 35.328054, -111.523053, null, 'Coconino National Forest Recreation', 'The Cinder Hills is a scenic recreation area enjoyed by many off-highway vehicle enthusiasts. Its numerous volcanic cinder cones and craters surrounded by a ponderosa pine forest environment gives the area its unique value. Due to a growing interest in this area for off-highway vehicle recreation, additional management direction is needed to protect sensitive resources and to provide for continuing use of this recreation. Approximately 13,500 acres in the Cinder Hills has been designated for off-highway vehicle recreation. Management emphasis is for the use of 2-, 3-, and 4-wheel vehicles.…', 'https://www.fs.usda.gov/recarea/coconino/recarea/?recid=70996', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '72114', 'McCoy Motorized Recreation Area', 'ohv_area', 44.691760, -122.039102, null, 'Willamette National Forest', 'Spectacular views of Mt. Jefferson and many peaks in the High Cascades highlight this family-friendly shared-use road system comprised of approximately 50 miles of easiest to more difficult roads open to motorized Class I, II, III, and IV users and highway vehicles. Motorized cross country travel is prohibited. Some paved segments are open to unlicensed (non-street legal) vehicles. Public lands managed by the US Forest Service are interspersed with private lands. Please use the area map in conjunction with the Motorized Vehicle Use Map to help guide you on which roads are open for motorized…', 'https://www.fs.usda.gov/recarea/willamette/recarea/?recid=72114', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '73965', 'Peters Mill Run/Taskers Gap OHV System', 'trail_system', 38.870000, -78.440000, null, 'George Washington & Jefferson National Forest', 'Known as the largest OHV trail system in the state of Virginia, Peters Mill Run and Taskers Gap OHV Trail System provides 36 miles of rugged adventure. Advanced riders will find challenges in steep, rocky and narrow trails, while others can enjoy trails that were once forest roads. All travelers will find mountain vistas, scenic rock outcroppings and the cool shade of deep forest. This trail has opportunities for Jeeps and other 4-wheeled drive vehicles, UTVs, ATVs, motorcycles, and electronic mountain bikes. Trail open to:', 'https://www.fs.usda.gov/recarea/gwj/recarea/?recid=73965', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74066', 'Mellor Ranch OHV Road 4S05', 'trail_system', 33.826046, -116.795629, null, 'San Bernardino National Forest', '3.8 miles from State Route 243 to the junction with 4S06 Indian Canyon OHV Road. All OHV laws apply.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74066', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74067', 'East Indian Creek OHV Road 4S10', 'trail_system', 33.763204, -116.823083, null, 'San Bernardino National Forest', '4.1 miles from junction of San Jacinto Ridge OHV Road 5S09 to Indian Canyon OHV Road 4S06', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74067', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74068', 'Indian Mountain OHV Road 4S21', 'trail_system', 33.797093, -116.777737, null, 'San Bernardino National Forest', '2.6 mile OHV Road 4S21 runs from State Highway 243 to the junction with San Jacinto Ridge OHV Road 5S09. This is a black diamond road with a few difficult rock gardens. 4WD vehicles with a short wheelbase are recommended.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74068', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74069', 'Miller Canyon OHV Staging Area', 'trailhead', 34.270128, -117.285917, null, 'San Bernardino National Forest', 'The Miller Canyon OHV Staging Area is located just east of Silverwood Lake State Recreation Area on Forest Road 2N37 off Highway 138. There is a vault toilet and a couple of picnic tables at the staging area along with ample parking and informational signs. NO OHV Camping permitted due to Forest Order 05-12-00-23-05 OCCUPANCY AND USE', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74069', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74070', 'Juan Diego OHV Road 6S89', 'trail_system', 33.608377, -116.795540, null, 'San Bernardino National Forest', 'This trail is closed due to the Fairview Fire. 1.6 miles runs from Red Mountain OHV Road 6S22 to Juan Diego Flat OHV Road 7S04', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74070', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74071', 'Juan Diego Flat OHV Road 7S04', 'trail_system', 33.597591, -116.782247, null, 'San Bernardino National Forest', 'This trail is closed due to the Fairview Fire. 3.5 miles and runs from Juan Diego OHV Road 6S89 to east of Reed Valley Road.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74071', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74101', 'Cleghorn Ridge OHV Road 2N47', 'trail_system', 34.299730, -117.456241, null, 'San Bernardino National Forest', '15.2 mile Green Sticker Route open to all OHV vehicles. This route runs from the Cleghorn off-ramp on Interstate 15 in Cajon Pass over Cleghorn ridge to end at State Highway 138. Expansive views of the desert are on the way up Cleghorn Ridge, then views of Lake Silverwood appear after cresting to the top. Note: although there are no staging areas at either entrances suitable for trailering, limited parking is available for vehicles. Additional staging area for trailering is Summit Staging area.The Summit Staging area requires a Recreation Pass. This OHV road is rated as easy to moderately…', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74101', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74144', 'Elliot Ranch OHV Road 3N22', 'trail_system', 34.320553, -117.430230, null, 'San Bernardino National Forest', 'Elliot Ranch OHV Road 3N22 runs from State Highway 138 to Cleghorn OHV Road 2N47 and is about one mile in length. Important Note The section of 3N22 from State Highway 138 to Summit OHV Staging Area is only open to street legal vehicles. Non-street legal vehicles must be carried via haul vehicle to the staging area - staging is not permitted along the highway.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74144', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74145', 'Baldy Mesa OHV Road 3N21', 'trail_system', 34.333095, -117.478135, null, 'San Bernardino National Forest', 'Baldy Mesa OHV Road 3N21 runs from the Baldy Mesa (Trestles) OHV Staging Area to the Desert Front OHV Road 3N24 which heads west to Baldy Mesa in the west Cajon valley. Important Note: 3N21 south towards SR 138 from the staging area is open to street-legal vehicles ONLY, all haul vehicles must transport non-street legal vehicles to the Baldy Mesa Staging Area. All roads heading east from the staging area are restricted to street legal vehicles - non-street legal vehicles can only travel approx 2.2 miles north to 3N24, then west on 3N24. This route is rated "Green Circle" easiest NO OHV…', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74145', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74146', 'Desert Front OHV Road 3N24', 'trail_system', 34.358401, -117.470165, null, 'San Bernardino National Forest', 'The Desert Front OHV Road 3N24 is commonly called "Baldy Mesa" and runs approx 10 miles from the junction of Baldy Mesa OHV Road 3N21 to State Highway 138 in west Cajon valley.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74146', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74147', 'Pilot Fuelbreak OHV Route 2N17X', 'trail_system', 34.302518, -117.302968, null, 'San Bernardino National Forest', 'This OHV road runs 3.3 miles from Pilot Rock OHV Road 2N33 just east of the Cedar Springs Dam at Lake Silverwood to Pilot Rock OHV Road 2N33. This road is classified as "most difficult"', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74147', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74148', 'Pilot Rock OHV Road 2N33', 'trail_system', 34.305142, -117.309762, null, 'San Bernardino National Forest', 'This road travels 11.8 miles from the Cedar Springs Dam at Lake Silverwood to State Highway 173 just north of Lake Arrowhead. Important Note: Non-street legal vehicles must exit 2N33 onto 3W14 just prior to waste treatment plant before State Highway 173. 3W14 is limited to vehicles less than 50" wide. Non-street legal vehicles greater than 50" wide cannot continue beyond this point.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74148', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74149', 'Pilot Rock Ridge OHV Road 2N36', 'trail_system', 34.282679, -117.271418, null, 'San Bernardino National Forest', 'This 1.9 mile OHV road connects Pilot Rock OHV Road 2N33 to Miller Canyon OHV Road 2N37, basically traveling from the top of the ridge down to the bottom of the canyon.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74149', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74150', 'Miller Canyon OHV Road 2N37', 'trail_system', 34.270172, -117.285480, null, 'San Bernardino National Forest', 'The Miller Canyon OHV Road 2N37 travels 5 miles from the Miller Canyon OHV Trailering Site to the junction of Pilot Rock OHV Road 2N33. Important Note: Non-street legal vehicles are not permitted west of the Miller Canyon Trailering Site (towards Lake Silverwood) all roads diverting to the south (right if you are heading up canyon) are restricted to street legal vehicles only.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74150', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74151', 'Crab Flats OHV Road 3N34', 'trail_system', 34.297642, -117.199298, null, 'San Bernardino National Forest', 'The Crab Flats OHV Road 3N34 is also known as the "Willow Creek Jeep Trail" on the west end and a portion just east of Deep Creek is known as "Dishpan Springs". The OHV road is just over 14 miles long and travels from State Highway 173 to Holcomb Valley OHV Road 3N16 at the Crab Flats Campground. Important Note: The portion of 3N34 between State Highway 173 and the Pinnacles OHV Staging Area is restricted to street legal vehicles only. Non-street legal vehicles must be transported to the Pinnacles OHV Staging Area, and not staged or ridden on State Highway 173. The portion of the road known…', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74151', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74152', 'Willow Bypass OHV Road 3N34X', 'trail_system', 34.298434, -117.197010, null, 'San Bernardino National Forest', 'The Willow Bypass runs from the Pinnacles OHV Staging area east for 1.3 miles over a challenging ridge to rejoin the Crab Flats OHV Road 3N34. The Bypass and Crab Flats OHV Road 3N34 are also known as the Willow Creek Jeep Trail . This bypass can have significant ruts.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74152', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74153', 'Ash Meadows OHV Road 2N75', 'trail_system', 34.280973, -117.169614, null, 'San Bernardino National Forest', 'The Ash Meadows OHV Road 2N75 runs just under 2 miles from Yosemite Drive in Lake Arrowhead to Crab Flats OHV Road 3N34. Important Note: Non-street legal vehicles are not permitted between Yosemite Drive and North Shore OHV Trail 3W65. There are no staging areas at 3W65.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74153', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74154', 'Skyline OHV Road 2N27Y', 'trail_system', 34.276246, -117.152784, null, 'San Bernardino National Forest', 'This road is just over one mile long and connects Banff OHV Road 2N28Y to Crab Flats OHV Road 3N34.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74154', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74155', 'Banff OHV Road 2N28Y', 'trail_system', 34.275912, -117.167476, null, 'San Bernardino National Forest', 'This road travels from the junction with North Shore Spur Road 2N96 (street legal only road) to the junction with Skyline OHV Road 2N27Y and Rouse Ranch OHV Road 2N25. Important Note: Rouse Ranch OHV Road is restricted to street legal vehicles only from 2N27Y/2N28Y to Torrey Pine Road. Also 2N96 is also street legal vehicles only.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74155', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74156', 'Rouse Ranch OHV Road 2N25', 'trail_system', 34.276097, -117.154151, null, 'San Bernardino National Forest', 'This road runs approx. 2.5 miles from Torrey Pine Road near SR 173 at the Lake Arrowhead dam to the junction with Crab Flat Road 3N34. Important Note: The section of 2N25 from the junction with 2N27Y/2N28Y is restricted to street legal vehicles only.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74156', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74157', 'Plantation OHV Road 2N29Y', 'trail_system', 34.277323, -117.160600, null, 'San Bernardino National Forest', 'This road runs approx a mile and a half from Banff OHV Road 2N28Y to Crab Flats OHV Road 3N34.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74157', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74159', 'Devils Hole OHV Road 3N34D', 'trail_system', 34.293139, -117.145314, null, 'San Bernardino National Forest', 'This OHV road is 1.75 miles long and runs from the junction of Crab Flats Road 3N34 to end of the road at Deep Creek. Motorcycle OHV Trail 2W01 begins at end of this road.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74159', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74160', 'Crab Flat Loop OHV Route 2N31Y', 'trail_system', 34.263724, -117.094526, null, 'San Bernardino National Forest', 'This is a 7/10 mile loop north of Crab Flats OHV Road 3N34, west of Crab Flats Campground.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74160', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74161', 'Holcomb Valley OHV Road 3N16', 'trail_system', 34.260691, -117.084410, null, 'San Bernardino National Forest', 'This road runs just over 26 miles from Green Valley Lake Road to the Dump Access Road near Baldwin Lake. Important Note: While the road is 26 miles long, only the 11 miles from the Crab Flats Campground junction with 3N34 to Forest OHV Road 3N56 are open to non-street legal vehicles. Reminder: 1. Non-street legal vehicles cannot use the portion of 3N16 to Green Valley Lake Road. 2. Non-street legal vehicles cannot use the portion of 3N16 from 3N56 to the Dump Access Road. 3. There is NO non-street legal vehicle roads or trails into the community of either Big Bear / Fawnskin nor Green Valley…', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74161', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74163', 'White Mountain Connector OHV Road 3N56', 'trail_system', 34.325774, -116.978179, null, 'San Bernardino National Forest', 'This short 2/10 mile OHV road connects Holcomb Valley OHV Road 3N16 to White Mountain OHV Road 3N17. Important Note : Non-street legal vehicles cannot travel east on 3N16 from 3N56.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74163', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74164', 'White Mountain OHV Road 3N17', 'trail_system', 34.328998, -116.977757, null, 'San Bernardino National Forest', 'This OHV road travels 8 miles over White Mountain to the junction with Grapevine Canyon OHV Road 4N16.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74164', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74166', 'Coxey OHV Road 3N14', 'trail_system', 34.343352, -117.064108, null, 'San Bernardino National Forest', 'This road travels 17.8 miles from Fawnskin to the northern Forest boundary, eventually ending up in the outskirts of Apple Valley. Important Note: Only street legal vehicles are permitted between Fawnskin and Holcomb Valley Rd. (3N16). OHV s that require a California DMV -issued identification sticker (e.g. green sticker) are now allowed to use the road between Holcomb Valley Rd. (3N16) and Grapevine Canyon Rd.(4N16), OHV access continues on to the north Forest boundary.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74166', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74168', 'Carbine Flat OHV Road 3N59', 'trail_system', 34.352945, -117.095125, null, 'San Bernardino National Forest', 'This road travels 4 miles from Coxey OHV Road 3N14 to the end. At the end of the road, motorcycle Devils Hole OHV Trail 2W01 begins towards Lake Arrowhead.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74168', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74169', 'Carbine Flat Spur A OHV Road 3N59A', 'trail_system', 34.352700, -117.105225, null, 'San Bernardino National Forest', 'This road travels 4.8 miles from the junction with Carbine Flat OHV Road 3N59 along the northern forest boundary terminating onto a BLM road. The road continues west on the BLM to Deep Creek Road in Hesperia.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74169', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74171', 'Wright Mine OHV Road 3N11', 'trail_system', 34.320649, -117.009553, null, 'San Bernardino National Forest', 'This 1.5 mile OHV road runs from Holcomb Valley OHV Road 3N16 to White Mountain OHV Road 3N17. Redonda Ridge OHV Trail 2W17 terminates here.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74171', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74172', 'Big Pine Flat OHV Road 3N92', 'trail_system', 34.332880, -117.020026, null, 'San Bernardino National Forest', 'This is a short one-mile route that connects Wright Mine OHV Road 3N11 to Redonda Ridge OHV Trail 2W17, allowing riders to loop back to Crab Flats using Holcomb Valley OHV Road 3N16.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74172', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74173', 'Smarts Ranch OHV Road 3N03', 'trail_system', 34.301015, -116.794299, null, 'San Bernardino National Forest', 'This road travels 7.4 miles from State Highway 18 in Cactus Flats into Lone Valley ending at the junction with Arrastre Creek Road 2N02. Important Note: 3N03 from State Highway 38 to the entrance to Cactus Flats OHV Staging Area is street legal vehicles only. Non-street legal vehicles must transported by haul vehicles to the Pinnacles OHV Staging Area. Forest 2N02 is street legal only from the junction of 2N02 of 3N03 west back towards Baldwin Lake.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74173', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74174', 'OHV Road 2N61Y', 'trail_system', 34.243544, -116.706833, null, 'San Bernardino National Forest', 'This 4.7 mile road is in the Rose mine area northeast of Big Bear and starts and ends on the OHV section of Arrastre Creek OHV Road 2N02.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74174', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74175', 'Arrastre Creek OHV Road 2N02', 'trail_system', 34.256135, -116.716766, null, 'San Bernardino National Forest', 'This road is just under 13 miles long and runs from Baldwin Lake Road to the eastern forest boundary, continuing on to Pioneertown in the Morongo Valley. Important Note: Non-street legal vehicles are only permitted from the junction with Smarts Ranch OHV Road 3N03 to the junction with OHV Road 2N61Y. Non-street legal vehicles are NOT permitted on 2N02 from Baldwin Lake Road to 3N03.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74175', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74176', 'Rattlesnake Canyon OHV Road 2N70Y', 'trail_system', 34.233584, -116.687152, null, 'San Bernardino National Forest', 'This loop road is just under a mile in length and runs from Arrastre Creek OHV Road 2N02 to OHV Road 2N69Y in the Rose mine / Tip Top Mountain area, northeast of Big Bear.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74176', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74177', 'OHV Road 2N69Y', 'trail_system', 34.235956, -116.688035, null, 'San Bernardino National Forest', 'This is a very short tenth of a mile connector road between Arrastre Creek OHV Road 2N02 and Rattlesnake Canyon OHV Road 2N70Y in the Rose Mine / Tip Top Mountain area, northeast of Big Bear.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74177', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74178', 'Tip Top Mountain OHV Road 2N90', 'trail_system', 34.255027, -116.710096, null, 'San Bernardino National Forest', 'This 1.8 mile road travels from Arrastre Creek OHV Road 2N02 up to the end on Tip Top Mountain, northeast of Big Bear.', 'https://www.fs.usda.gov/recarea/sbnf/recarea/?recid=74178', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74995', 'Mountain Man Trailhead', 'trailhead', 35.529918, -92.839323, null, 'Ozark-St. Francis National Forests', 'The Mountain Man Trailhead provides access to the Brock Creek Multi-Use Trail System.', 'https://www.fs.usda.gov/recarea/osfnf/recarea/?recid=74995', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74996', 'Austin Trailhead', 'trailhead', 35.536206, -92.803724, null, 'Ozark-St. Francis National Forests', 'The Austin Trailhead provides access to the Brock Creek Multi-Use Trail System.', 'https://www.fs.usda.gov/recarea/osfnf/recarea/?recid=74996', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '74997', 'Zing Trailhead', 'trailhead', 35.510618, -92.826227, null, 'Ozark-St. Francis National Forests', 'The Zing Trailhead provides access to Brock Creek Multi-Use Trail System.', 'https://www.fs.usda.gov/recarea/osfnf/recarea/?recid=74997', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '77375', 'Superior OHV System', 'trail_system', 38.674900, -82.692700, null, 'Wayne National Forest', 'Superior OHV Trail System is currently 16.5 miles long. A trailhead off State Route 52 accesses this section of trail. The trail also has two connector trails to the Pine Creek OHV Trail System for continuous riding opportunities and additional traihead access points. The trail system is open to all-terrain vehicles (ATVs), off-highway motorcycles (OHMs), mountain bikes, and hiking. Trail width limit is 50 inches. Trailhead Superior Trailhead', 'https://www.fs.usda.gov/recarea/wayne/recarea/?recid=77375', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '79504', 'Eshom Point OHV Staging Area', 'trailhead', 36.644444, -118.946111, null, 'Sequoia National Forest', 'Eshom Staging Area, also known as Eshom Point is currently open to Off-Highway Vehicle Use. Please remember to follow posted rules and regulations. Its important to remember that all users must operate their off-highway vehicle with a valid California Green Sticker, and helmet. All users: Please stay on designated roads.', 'https://www.fs.usda.gov/recarea/sequoia/recarea/?recid=79504', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '79555', 'Millwood OHV Staging Area', 'trailhead', 36.743000, -119.002000, null, 'Sequoia National Forest', 'Millwood is a developed OHV staging area with a few campsites, vault toilets, steel fire ring and tables. Millwood area provides access to various out & back routes and loop routes that can challenge OHV drivers and riders. Goodmill OHV route is one of the most popular, is an intermediate route with creek crossing and intermediate hill climbs. Average elevation is 5,000’.The Old Shay Rail road is an advanced route for motorcycle and ATV''s only. OHV maps of the Hume Lake District can be found at the District Office in Dunlap California. Open Monday-Friday from 8am-4:30pm. Closed on federal…', 'https://www.fs.usda.gov/recarea/sequoia/recarea/?recid=79555', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '79596', 'Woodward OHV Staging Area', 'trailhead', 36.692000, -118.870000, null, 'Sequoia National Forest', 'Woodward is an undeveloped staging area with in facilities and located &frac14; mile south of Montecito Sequoia Resort on the General''s Highway. In the summer this trailhead provides access to Woodward (FS 14S18) ,Starlight (14S14), and many other roads.', 'https://www.fs.usda.gov/recarea/sequoia/recarea/?recid=79596', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '79683', 'Cyrus Canyon OHV Park', 'park', 35.706225, -118.415265, null, 'Sequoia National Forest', 'Cyrus Canyon OHV Park is located northeast of Lake Isabella at an elevation of 2,600 ft. This motorcross loop trail is a great opportunity for family outings OHV riding or even an organized event. It is open for use by ATVs, Quads, and motorcycles. A small flat area adjacent to the parking lot provides a safe place for beginners. The main loop trail offers a variety of challenges for the more experienced rider. Steep slopes, sharp turns, jumps, and hills add to the excitement of the course.', 'https://www.fs.usda.gov/recarea/sequoia/recarea/?recid=79683', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '79936', 'Cherry Gap OHV Staging Area', 'trailhead', 36.777800, -118.959770, null, 'Sequoia National Forest', 'Cherry Gap is an undeveloped staging area with dispersed camping nearby. Remember when dispersed camping to pack out what you pack in and follow leave no trace methods. Also check fire restrictions for the local area.', 'https://www.fs.usda.gov/recarea/sequoia/recarea/?recid=79936', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80198', 'Holy Cross City Jeep Road TH #759', 'trailhead', 39.403272, -106.443529, null, 'White River National Forest', 'This extreme road starts off Homestake Road #703 and ends at Holy Cross City historic site. This is one of the more difficult and popular roads in the state. Consult a 4-wheel drive guidebook for a detailed description of this route and recommended vehicle specifications. Stock vehicles should not attempt this one.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=80198', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80251', 'McAllister Gulch Road TH #708', 'trailhead', 39.448489, -106.319997, null, 'White River National Forest', 'McAllister Gulch Road #708 begins at Camp Hale and ends at Shrine Pass Road #709. This is a rough 4WD road that requires a high-clearance 4WD vehicle. It does provide excellent views near the top of both Resolution Mountain and Hornsilver Mountain.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=80251', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80333', 'Wearyman Road #747', 'trail_system', 39.523665, -106.325619, null, 'White River National Forest', 'This rugged dirt road starts at Shrine Pass Road #709 and ends at Resolution Road #702 near the top of Ptarmigan Pass. It has several creek crossings and rocky sections requiring a high-clearance 4WD vehicle. There are panoramic views at the top of Ptarmigan Pass, where the much easier Resolution Road #702 then descends down to Camp Hale. Click here to see a Recreation Quicksheet for this road, complete with directions, description, map, and more.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=80333', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80398', 'Aldrich Lakes Rim #2251', 'trail_system', 40.152763, -107.696806, null, 'White River National Forest', 'The Aldrich Lakes Rim Trail runs east-west from FS251 to FS252. The east end of the trial is rocky and rutted, and requires technical skills to traverse safely. It is not recommended for beginners.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=80398', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80600', 'Humbug OHV Recreation Area', 'ohv_area', 41.775023, -122.728549, null, 'Klamath National Forest', 'The Humbug OHV Area, located on the Happy Camp/Oak Knoll Ranger Districts, provides riders with 14 miles of trails (open to vehicles 50 inches or less in width), a youth riding area, and 5 acres of open riding terrain. It has a day use parking area, picnic tables, two campsites, vault toilets, and a loading/unloading ramp. In addition, the Happy Camp/Oak Knoll Ranger Districts offer 695 miles of road open to OHV use. For details about roads open to off-highway vehicles please pick up a current copy of the Klamath National Forest Motor Vehicle Use Map, which is available free of charge at all…', 'https://www.fs.usda.gov/recarea/klamath/recarea/?recid=80600', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80601', 'Juniper Flat OHV Area', 'ohv_area', 41.568851, -122.267260, null, 'Klamath National Forest', 'Currently closed - no estimation on when it will reopen. The Juniper Flat OHV recreation area is a popular destination for off road riders from the Yreka, Weed and Mt Shasta Areas. It is located in the Shasta Valley in a flat area of sandy soils and lava flows amidst juniper and sage vegetation. Juniper Flat is approximately 15 miles from Weed and 25 miles from miles from Yreka and Mt. Shasta. The Juniper Flat OHV Area, located on the Goosenest Ranger District, provides riders with 48 acres of open riding terrain and has a day use parking area, picnic tables, vault toilets, and a…', 'https://www.fs.usda.gov/recarea/klamath/recarea/?recid=80601', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80625', 'Ditch Creek Trailhead', 'trailhead', 43.960529, -103.841568, null, 'Black Hills National Forest', 'Ditch Creek Trailhead is located about 15 miles west of Hill City on Deerfield Road, then 4 miles south of Deerfield Road on Ditch Creek Road, adjacent to the Ditch Creek Camp Ground.', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80625', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80626', 'Red Fern Trailhead', 'trailhead', 44.023074, -103.653838, null, 'Black Hills National Forest', 'Red Fern Trailhead', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80626', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80628', 'Shanks Trailhead', 'trailhead', 44.065525, -103.380651, null, 'Black Hills National Forest', 'Access the Shanks Trailhead from Rapid City. Travel Highway 44 west for 5 miles, turn North (right) onto Forest Road 603. Travel 0.5 miles, trailhead will be on left in the bottom of the quarry.', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80628', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80629', 'Schroeder Trailhead', 'trailhead', 44.081965, -103.373749, null, 'Black Hills National Forest', 'Access the Schroeder Trailhead from Rapid City. Drive 3 miles west of Rapid City on Nemo Road to Schroeder Road, turn west (left) and proceed through residential area for about 2 miles. The trailhead will be on the left as you approach the Forest boundary.', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80629', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80631', 'Stageyard Trailhead', 'trailhead', 44.243000, -103.880000, null, 'Black Hills National Forest', 'Stageyard Trailhead provides access to six OHV trails that are open to vehicles 62-inch in width or less. The trails are a popular with hunters during the fall and during the summer the trails provide a family OHV experience. The scenic trails are primarily on old logging roads that wind through Ponderosa Pines and stands of Black Hills Spruce. Access the Stageyard Trailhead from Cheyenne Crossing (intersection of US Highways 14A and 85) travel 0.1 mile west on US-85 S, and turn south (left) on Hanna Road / National Forest System Road (NFSR) 196. Travel south 3.5 miles, passing Hannah…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80631', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80632', 'Riley Hill Trailhead', 'trailhead', 44.132357, -103.635892, null, 'Black Hills National Forest', 'Riley Hill Trailhead offers extensive access to a wide variety of trails from just south of Roubaix Lake Recreation Area to north of Pactola Reservoir. Trails range from old logging roads for a peaceful OHV ride, to narrow single track for the more adventurous, and have a wide variety in-between. This series of trails has something for almost everyone. Access the Riley Hill Trailhead from Deadwood, via US Highway 385 south. Travel on US 385 S for 19.5 miles to Rochford Road, turning west (right). Proceed approximately 4.1 miles west towards Rochford, SD. After approximately 4.1 miles turn…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80632', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80634', 'Camp 5 Trailhead', 'trailhead', 44.384251, -103.616767, null, 'Black Hills National Forest', 'The Camp 5 Motorized Trailhead is the most popular gateway to over 10 miles of rock-crawling, 4x4, and OHV routes in the Deadwood area. Many of these trails can be very challenging and test the limits of operators and machines. Several of the trails wind in and out of creek beds, through boulder fields, and up and down waterfalls as they navigate around steep canyons and pine forests. The trails south of the trailhead are popular with 4x4 clubs, rock-crawling enthusiasts, and adventure-seekers throughout the region. The two trails to the west of the trailhead (Trails 8041 and 8040) are…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80634', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80635', 'Spearfish Quarry Trailhead', 'trailhead', 44.461559, -103.914386, null, 'Black Hills National Forest', 'The Forest Service designed the Spearfish Quarry Trailhead for beginners to practice their motorized riding skills. The former gravel pit near the parking area is open to cross-country travel and there are four short trails accessible from the trailhead. Access the trailhead from Spearfish via Interstate 90, Exit 8, traveling south on McGuigan Road which merges to Tinton Road. Stay on Tinton Road (also National Forest Service Road, NFSR 134) for 1.6 miles. At Trail 8000, turn west (right) and proceed approximately 0.1 mile to the trailhead. [There is also a non-motorized trailhead on the east…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80635', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80637', 'Piedmont Trailhead', 'trailhead', 44.226767, -103.402259, null, 'Black Hills National Forest', 'The Piedmont Trailhead is on the east side of the most popular system of trails in the Northern Hills. The trails west of Piedmont wind through Ponderosa Pine forests, meander through large meadows, and climb to some of the most spectacular vistas in the Black Hills. The majority of the area trails are open from May 15 Dec 15, with a few trails that stay open year-around. Access the Piedmont Motorized Trailhead from Rapid City from Interstate 90 to Exit 46. Turn west (left) on Meade County Highway MC-4 / Elk Creek Road. Proceed to the intersection with Sturgis Road and turn north (right) on…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80637', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80639', 'Reuter Trailhead', 'trailhead', 44.426082, -104.425653, null, 'Black Hills National Forest', 'Reuter Motorized Trailhead provides access to a large variety of recreation activities. There is immediate access to trails for hiking, biking, horse-back riding, and Nordic skiing through the Carson Draw Trails. The trailhead is an alternative parking area to the Ogden Creek Trailhead for OHV riders. Finally, it is the primary trailhead for the snowmobile trails that travel up Warren Peak Highway and run the 67 miles through the Bearlodge Mountains. Toilets are available at the Reuter Campground. To access the Reuter Motorized Trailhead from Sundance (Exit 185 of Interstate 90), travel…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80639', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80641', 'Blacktail Trailhead', 'trailhead', 44.578232, -104.484106, null, 'Black Hills National Forest', 'Blacktail Motorized Trailhead is the primary gateway to dozens of miles of OHV trails west of Cook Lake. The trailhead provides access to extensive OHV routes on the Bearlodge Ranger District and has some of the most challenging routes on the district. The area is also popular with hunters during the fall and typically provides excellent hunting opportunities. Trails are open to OHVs 50-inch wide or less. Access Blacktail Motorized Trailhead from Hulett, WY via WY Highway 24W travel 1.3 miles southwest to Crook County Road (209) (Black Tail Road). Turn southeasterly (left) on Crook County…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80641', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80643', 'Red Lake Trailhead', 'trailhead', 44.338962, -103.990351, null, 'Black Hills National Forest', 'The Forest Service designed Red Lake Trailhead for a family experience. The OHV trails travel across old logging roads and through scenic Aspen groves that are particularly nice in the fall. The trails also allow for riders to park their OHVs and access hiking routes, such as Buzzards Roost, that overlook the Spearfish Canyon. The trails are open from May 15 December 15 to vehicles of 62-inch width or less. OHVs may travel on all routes marked or mapped as open. The gravel pit and piles near the parking area are not open to OHV use. Access Red Lake Trailhead from Spearfish from Interstate 90,…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80643', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80644', 'Richardson Trailhead', 'trailhead', 43.595372, -103.796195, null, 'Black Hills National Forest', 'Richardson Trailhead is located approximately 20 miles southwest of Custer, SD and it provides access to the Martin ATV Trail system, which is comprised of 52 miles of scenic loop trails open to vehicles 62 or less in width. A trail permit is required to use these trails. A bulletin board is on site with information and maps available to the public.', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80644', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '80645', 'Bluebird Trailhead', 'trailhead', 43.612225, -103.731827, null, 'Black Hills National Forest', 'Bluebird Trailhead is located approximately 15 miles southwest of Custer, SD and it provides access to the Martin ATV Trail system, which is comprised of 52 miles of scenic loop trails open to vehicles 62 or less in width. A trail permit is required to use these trails. A bulletin board is on site with information and maps available to the public.', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=80645', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81080', 'Ogden Creek Trailhead', 'trailhead', 44.463000, -104.412000, null, 'Black Hills National Forest', 'The Ogden Creek Motorized Trailhead provides access to four OHV trails southeast of Warren Peak. The trailhead is approximately 10 miles from Sundance and provides close access for local riders. The trails are open to vehicles with 50-inch width or less. This trailhead is also one of the four trailheads serving the 47.3 miles of stacked-loop non-motorized Sundance Trails. To access the Ogden Creek Motorized Trailhead from Sundance (Exit 185 of Interstate 90), travel northwest on US14 for approximately 0.9 miles to Crook County 63, National Forest Service Road (NFSR) 838. Turn north (right)…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=81080', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81166', 'Johnson Canyon Trailhead', 'trailhead', 45.964935, -111.053524, null, 'Custer Gallatin National Forest', 'Trailhead providing access to National Forest land on the western side of the northern Bridgers. No facilities are located at the end of the road and there are no maintained trails. OHV riding and hiking are available on trails in the area.', 'https://www.fs.usda.gov/recarea/custergallatin/recarea/?recid=81166', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81442', 'Bishop Park (Olson/Miles Creek Trailheads)', 'park', 45.799407, -110.871676, null, 'Custer Gallatin National Forest', 'Multiple trailheads and connector routes for loop or out and back hiking, mountain biking and OHV riding. Refer to Forest Maps and Motor Vehicle Use Maps for seasonal riding and designation dates.', 'https://www.fs.usda.gov/recarea/custergallatin/recarea/?recid=81442', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81443', 'Jackson Creek Trailhead', 'trailhead', 45.726461, -110.763358, null, 'Custer Gallatin National Forest', 'OHV designated trail riding area providing multiple connector trails. Refer to Forest Map and Motor Vehicle Use Map for seasonal designations', 'https://www.fs.usda.gov/recarea/custergallatin/recarea/?recid=81443', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81520', 'Huckleberry Flats OHV Trailhead & Staging Area', 'trailhead', 43.842727, -122.375141, null, 'Willamette National Forest', 'This is the trailhead and staging area for Huckleberry Flats OHV Trail . See trail page for more information, including a map, rules for OHV riding and more.', 'https://www.fs.usda.gov/recarea/willamette/recarea/?recid=81520', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81731', 'Figueroa OHV Recreation Area', 'ohv_area', 34.744022, -119.984467, null, 'Los Padres National Forest', 'Catway Jeep Trail 29W02 - Temporarily closed 11/25/2024 - Figureoa Mountain OHV Area. This 2.5 mile long narrow trail is a connecter from Sunset Valley Rd. to Catway/Zaca Ridge Rd. More difficulty. Zaca Ridge/Catway Road 8N02 - Temporarily cosed due to wet weather conditions 11/25/2024 - This route begins at Figueroa Mountain Road and follows Zaca Ridge until it meets at a dead-end. Easiest East Pinery OHV Rd 8N32 - Open - This is a easy 1.7 mile one way trail with an elevation gain of 459 ft.', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=81731', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81850', 'Goldhill Camping Area', 'trail_system', 34.703700, -118.937100, null, 'Los Padres National Forest', '8/1/2024 ALERT - Contact the Mt. Pinos District office for current access information to the Goldhill area. Due to the Post Fire, this area may not be accessible. Goldhill Camping Area is an open camping location adjacent to Piru Creek at the base of Alamo Mountain. Recreational Vehicles up to 26 feet. Picnic tables, fire rings, toilets. No potable water available. Located near several Forest Service Off-Highway Vehicle (motorcycle and four-wheel drive) roads and trails and is approximately eight miles southwest of Hungry Valley State Vehicular Recreation Area. In 1889, John L. Henderson made…', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=81850', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81856', 'Frazier Mountain Trailhead - 20W03', 'trailhead', 34.802400, -119.009200, null, 'Los Padres National Forest', 'Forest Development Road 20W03 is also known as OHV Trail 118 on the Mt Pinos Motor Vehicle Guide (OHV Map) Difficulty: easy Length: 6.0 miles Maps: 7.5 minute USGS topographic maps (Cuddy Valley) The Frazier Mountain Trailhead (elev. 5400 ft.) is located on the west side of Frazier Mountain Road (8N04) approximately &frac34; mile south of Lockwood Valley Road and Forest Service Chuchupate Ranger Station. There is a large paved parking lot with pull-through stalls for vehicles with trailers or motor homes and a vault toilet at the trailhead. The signed Off Highway Vehicle trail starts at the…', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=81856', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81880', 'Turkey Flat OHV Campground/Staging Area/Trailhead', 'trailhead', 35.348690, -120.350980, null, 'Los Padres National Forest', 'The site is located on Navajo Road, one quarter of a mile off Parkhill Road. The trailhead parking serves Motorcycles ATV''s. Open daily and year-round, Turkey Flat Campground has an open area of campsites that include picnic tables and two vault toilets. You should plan to be completely self-sustainable for the duration of your trip. There is no potable water (drinking water) onsite. There is no dump station. Near the fee/information boards is a staging area to offload gear. There is a vault toilet and several picnic tables in a flat area under large oak trees for shade. Powerline and La…', 'https://www.fs.usda.gov/recarea/lpnf/recarea/?recid=81880', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81940', 'Santiam Pass OHV Motorized Recreation Area', 'ohv_area', 44.390467, -121.860950, null, 'Willamette National Forest', 'Family-focused Recreation in the High Cascades The Santiam Pass OHV Motorized Recreation Area is open to both motorized (all vehicle classes) and non-motorized users (hiking, stock, mountain bikes). The family friendly area includes kiddy loops for the smallest OHV enthusiasts. The area hosts designated travel routes and facilities, delivering a sustainable motorized trail system to the public. The area has designated trails for all classes of OHV and provides a diversity of difficulties ranging from Green Circle to Double Black Diamond trails. Motorized cross country travel is not allowed.…', 'https://www.fs.usda.gov/recarea/willamette/recarea/?recid=81940', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81987', 'Blair Mountain TH #601.1', 'trailhead', 39.845279, -107.578567, null, 'White River National Forest', 'Blair Mountain is accessed off the Buford New Castle Road #245. It is approved for high clearance full sized vehicles, OHV, bike, horse and foot travel. The trail is 17 miles, and is extremely rough in sections with a series of rock steps in one area. You may encounter domestic sheep and livestock protection dogs. Do not approach the dogs; they may be aggressive if they perceive a threat.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=81987', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '81988', 'Blair Overlook TH #601.2E', 'trailhead', 39.807794, -107.424798, null, 'White River National Forest', 'Blair Overlook is accessed off #601.1. It is accessible to full sized, high clearance vehicles, OHVs, bikes, horses and foot traffic. The trail to the overlook is just over 1/2 mile.', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=81988', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '82044', 'Bogus System', 'trail_system', 44.125000, -103.471944, null, 'Black Hills National Forest', 'The Bogus Trail System is enclosed by Bogus Jim Road to the north, Norris Peak Road to the east, Highway 44 to the south and Highway 385 to the west. This is a very rough and rocky trail system containing roughly 34 miles of trail. Technical motorcycle trails and rock crawler routes are the majority of this trail system. These trails are open yearlong. There is no developed trailhead for these trails, but there are a few popular access points with some parking. Rock crawler trails are best accessed off Bogus Jim Road. From Rapid City, travel West on highway 44 for approximately 11 miles, then…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=82044', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '82046', 'Merritt System', 'trail_system', 44.105000, -103.561667, null, 'Black Hills National Forest', 'The Merritt Trail System is a 41 mile mix of motorcycle, jeep and OHV trails, located west of Highway 385, south of Rochford Road, and north of Silver City Road. This is a popular area that connects the Minnesota Ridge Trail System of the Northern Hills trails to the Central Hills. While the motorcycle trails may be a little challenging, the remaining trails are excellent for all users. There is one trailhead for parking in this area. Some of these trail are open yearlong, and some are open May - December 15. Riley Trailhead. From Rapid City, Travel west on Highway 44 for 15 miles, then turn…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=82046', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '82049', 'Newton System', 'trail_system', 43.975833, -103.675833, null, 'Black Hills National Forest', 'The Newton Trail System is just west of Hill City about 5 miles nestled between Deerfield Road and Reno Gulch Road. The 50 miles of trail is predominantly designed for OHV use, but there is one motorcycle trail that will challenge you. This trail system is wider and faster than others in the area, and will provide amazing views of Black Elk Peak and the surrounding area. It is not uncommon to see elk and the occasional mountain lion in the area as well. To access the Newton Trails, travel north out of Hill City on Deerfield Road for 7.7 miles. Turn south (left) onto Newton Fork Road, and…', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=82049', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '82064', 'Hawkwright Trailhead', 'trailhead', 43.664000, -103.790000, null, 'Black Hills National Forest', 'Scenic Loop Trails Hawkwright Trailhead is located approximately 15 miles southwest of Custer, SD and it provides access to the Martin ATV Trail system, which is comprised of 52 miles of scenic loop trails open to vehicles 62 or less in width. A trail permit is required to use these trails. A bulletin board is on site with information and maps available to the public.', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=82064', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '82065', 'Antelope Springs Trailhead', 'trailhead', 43.970000, -104.008000, null, 'Black Hills National Forest', 'Antelope Springs Trailhead is located approximately 32 miles northwest of Custer, SD. This trailhead is used primarily for motorized vehicles and for day-use motorized trail users. It has a large parking lot suited to park several trucks and trailers. A trail permit is required to use these trails and a bulletin board is on site with information and maps available to the public. Antelope Springs Trailhead. This trailhead is used primarily for motorized vehicles.', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=82065', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '82066', 'Coal Ridge Trailhead', 'trailhead', 43.418000, -103.852000, null, 'Black Hills National Forest', 'Coal Ridge Trailhead is located approximately 35 miles southwest of Custer, SD and it provides access to the Coal Ridge trail system, which is comprised of 2.5 miles of scenic loop trail open to vehicles 62 or less in width. A trail permit is required to use these trails. A bulletin board is on site with information and maps available to the public.', 'https://www.fs.usda.gov/recarea/blackhills/recarea/?recid=82066', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '82766', 'Interface OHV Area', 'ohv_area', 38.289937, -120.339817, null, 'Stanislaus National Forest', 'The Interface Off-Highway Vehicle Area is located near Arnold, California. Based on seasonal designations found in the Motor Vehicle Use Map, this area is closed from December 15th through April 15th. For a free copy of the most recent Motor Vehicle Use Map, please see below. Call the Calaveras Ranger Station at 209-795-1381 to check on the status of the Interface OHV Area. This area used to be known as the White Pines OHV Area, but the name was changed to Interface OHV Area in 2009. There is an upper and lower staging area with picnic tables, loading ramps, informational kiosks, and portable…', 'https://www.fs.usda.gov/recarea/stanislaus/recarea/?recid=82766', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '82942', 'Windy Point Bypass TH #1846', 'trailhead', 39.598553, -107.314324, null, 'White River National Forest', 'The Windy Point Bypass is a motorized trail located north of Glenwood Springs. The Bypass is 3 miles long, beginning and ending at intersections with Transfer Trail #602 . As its name suggests, the Bypass provides an alternate route for visitors who wish to avoid following Transfer Trail around Windy Point. The Bypass is particularly useful during the spring and fall, when snow banks on Windy Point can make travel hazardous. The Windy Point Bypass is rough and narrow, with mid to moderate grades. The Bypass leads visitors through an evergreen forest with occasional views of the surrounding…', 'https://www.fs.usda.gov/recarea/whiteriver/recarea/?recid=82942', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83087', 'Belle Starr North Parking/Trailhead', 'trailhead', 34.991000, -94.350000, null, 'Ouachita National Forest', 'The North Parking/Trailhead provides access to the Belle Starr Multi-Use Trail', 'https://www.fs.usda.gov/recarea/ouachita/recarea/?recid=83087', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83088', 'Belle Starr West Parking/Trailhead', 'trailhead', 34.969000, -94.424000, null, 'Ouachita National Forest', 'The West Parking/Trailhead provides access to the Belle Starr Multi-Use Trail', 'https://www.fs.usda.gov/recarea/ouachita/recarea/?recid=83088', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83094', 'Red Spring Singletrack', 'trail_system', 31.630864, -111.102437, null, 'Coronado National Forest', 'The Red Spring Singtrack area is located approximately 4 miles west of Exit 40, Chavez Siding, off of Interstate 19. Access is from Forest Service Road 684. A staging area provides parking for vehicles and trailers. There are two Ramadas and picnic tables available. The trail rolls through 25 miles of spectacular rugged scenery. While it was primarily designed for singletrack dirt bikes and mountain bikes, it is a multi-use trail that is open, though not recommended, to non-motorized recreation, including hiking and equestrian use. Share the trail - Tread Lightly YIELDING: Yield the right of…', 'https://www.fs.usda.gov/recarea/coronado/recarea/?recid=83094', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83328', 'Muckamuck #346', 'trail_system', 48.621182, -119.846464, null, 'Colville National Forest', 'This 1.6 mile more difficult trail climbs to the top of Muckamuck Mountain, eventually travelling through some old growth Douglas fir. The trail then opens to a grassy hillside where there are great panoramic views of the area. This trail is used frequently by motocycle riders, but hikers can access it.', 'https://www.fs.usda.gov/recarea/colville/recarea/?recid=83328', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83467', 'Granite View Trailhead', 'trailhead', 48.519161, -119.852400, null, 'Colville National Forest', 'This trail is designed for OHVs and access the Granite Mountain Trail #365 and adjacent Forest Service Roads in the area. The trail is usually snowed in until June. Access to this area generally opens by May.', 'https://www.fs.usda.gov/recarea/colville/recarea/?recid=83467', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83518', 'Snow Dog Trailhead', 'trailhead', 48.552315, -119.857708, null, 'Colville National Forest', 'OHV Trailhead that accesses the road system and motocycle trails in the area.', 'https://www.fs.usda.gov/recarea/colville/recarea/?recid=83518', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83600', 'Silver Lake OHV Trailhead', 'trailhead', 30.403800, -84.408000, null, 'National Forests in Florida', 'Off-highway vehicle (OHV) trailhead access for the all terrain vehicle (ATV) trail system. The parking area is located inside Silver Lake Recreation Area , off to the right as you enter the recreation area.', 'https://www.fs.usda.gov/recarea/florida/recarea/?recid=83600', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83637', 'Springhill Motorcycle Trailhead', 'trailhead', 30.362300, -84.370400, null, 'National Forests in Florida', 'Trailhead for the off-road motorcycle trail system in the Apalachicola National Forest.', 'https://www.fs.usda.gov/recarea/florida/recarea/?recid=83637', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83655', 'Delancy West OHV Trailhead', 'trailhead', 29.444869, -81.738031, null, 'National Forests in Florida', 'Trailhead along SR 19 for the Delancy Loops and the Ocala North OHV Trail System. OHV Riding To ride our OHV trails, you''ll need a pass and safety gear. Riders under 16 must pass an online course. Our OHV web page has all the information you need for a safe, enjoyable trip. Camping Dispersed/Primitive Camping Many people enjoy this solitude and primitive experience, but knowing your limits, skills and abilities is a must. Following certain rules and regulations will help make your experience safer and ensure settings remain unspoiled.', 'https://www.fs.usda.gov/recarea/florida/recarea/?recid=83655', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83658', 'Pipeline OHV Trailhead', 'trailhead', 29.368495, -81.850691, null, 'National Forests in Florida', 'The 19-mile Pipeline OHV Trail is one of the easiest OHV trails to access within the Ocala National Forest, with a prominent trailhead along SR 316 between Salt Springs and Eureka. Open to motorcycles and ATVs, the trail includes some sharply banked curves through the scrub at the north end of the northernmost of the three stacked loops. Use the Pipeline Trail to access to the Tobacco Patch OHV Trail, Hog Valley OHV Trail, Longleaf OHV Trail and the Motorcycle Loop. OHV Riding To ride our OHV trails, you''ll need a pass and safety gear. Riders under 16 must pass an online course. Our OHV web…', 'https://www.fs.usda.gov/recarea/florida/recarea/?recid=83658', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83659', 'Rodman OHV Trailhead', 'trailhead', 29.501207, -81.815545, null, 'National Forests in Florida', 'Trailhead for northern access to the Ocala North OHV Trail System. Located near the Rodman Reservoir. OHV Riding To ride our OHV trails, you''ll need a pass and safety gear. Riders under 16 must pass an online course. Our OHV web page has all the information you need for a safe, enjoyable trip. Camping Dispersed/Primitive Camping Many people enjoy this solitude and primitive experience, but knowing your limits, skills and abilities is a must. Following certain rules and regulations will help make your experience safer and ensure settings remain unspoiled.', 'https://www.fs.usda.gov/recarea/florida/recarea/?recid=83659', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83663', 'Centennial OHV Trailhead', 'trailhead', 29.172315, -81.756211, null, 'National Forests in Florida', 'The Centennial Trailhead provides parking and northern access to the 47-mile Ocala Centennial Trail. Various sites and facilities are located along the trail. At Blue Sink and Farles Prairie, visitors can take a break from riding and enjoy some fishing, wading, picnicking, and wildlife viewing. Special OHV parking corrals are located periodically along the trail so riders can stop at the day-use recreation sites and at Big Scrub Campground. Corrals are only for parking, not for loading and unloading trailered vehicles. This trailhead provides access to trails for ATVs, UTVs and motorcycles.…', 'https://www.fs.usda.gov/recarea/florida/recarea/?recid=83663', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83699', 'Motorcycle Loop OHV Trailhead', 'trailhead', 29.428755, -81.823059, null, 'National Forests in Florida', 'With twisting, winding narrow trails through longleaf pine and scrub forest, the Motorcycle Loop is a physical challenge and open to motorcycles only. Access this 14-mile system of stacked loops from the Motorcycle Loop Trailhead along FR 66 west of Lake Delancy, or from a number of connecting trails - the Hog Valley Trail, Tobacco Patch Trail, Longleaf Pine Trail and Pipeline Trail. The Ocala North OHV Trail System offers 125 miles of trail which includes a 14-mile motorcycle-only trail; 35 miles of trail usable by motorcycles, all terrain vehicles (ATVs), and utility vehicles (UTVs) less…', 'https://www.fs.usda.gov/recarea/florida/recarea/?recid=83699', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83717', 'Big Scrub Campground', 'trail_system', 29.051500, -81.755200, null, 'National Forests in Florida', 'Popular with OHV enthusiasts, the 47-site Big Scrub Campground is in the heart of the Big Scrub in the south central portion of the Ocala National Forest. A trailhead provides riders campsite-to-trail access for the Ocala Centennial Trail. Camping Tents, campers and RVs are welcome at Big Scrub Campground, where we have showers, restrooms and drinkable water. OHV Riding Campers with ATVs are also welcome, where there is direct access from the campground to the 47-mile Ocala Centennial Trail.', 'https://www.fs.usda.gov/recarea/florida/recarea/?recid=83717', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '83721', 'Lake Delancy West OHV Campground', 'trail_system', 29.429349, -81.788609, null, 'National Forests in Florida', 'Lake Delancy West is an OHV recreation area along Lake Delancy that houses OHV corrals, access to numerous marked OHV trails along the Ocala North OHV Trail System and camping along the lake. The recreation area also serves as a trailhead and designated campground along the hiking-only Florida Trail. Camping Tent and small trailer camping is available at 30 sites within the pine forest along the western shore of Lake Delancy. All sites are within close proximity to the OHV corral, the Ocala North OHV Trail System and the Florida Trail. Heads up: Bears do frequent this area. You are required…', 'https://www.fs.usda.gov/recarea/florida/recarea/?recid=83721', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '84209', 'KC Pavilion Trailhead', 'trailhead', 36.894416, -93.107669, null, 'Mark Twain National Forest', 'This is one of the three trailheads for the Chadwick Trail System . The other two are Oak Camp and Camp Ridge . Riders can also access the trail from Cobb Ridge Campground . This also a picnic site, with a pavilion.', 'https://www.fs.usda.gov/recarea/mtnf/recarea/?recid=84209', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '84210', 'Camp Ridge Trailhead', 'trailhead', 36.901187, -93.113543, null, 'Mark Twain National Forest', 'This is one of the three trailheads for the Chadwick Motorized Trail System . The other two are KC Pavilion and Oak Camp . Riders can also access the trail from Cobb Ridge Campground . This site has picnic facilities.', 'https://www.fs.usda.gov/recarea/mtnf/recarea/?recid=84210', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '84211', 'Oak Camp Trailhead', 'trailhead', 36.873763, -93.093860, null, 'Mark Twain National Forest', 'This is one of the three trailheads for the Chadwick Trail System . The other two are KC Pavilion and Camp Ridge . Riders can also access the trail from Cobb Ridge Campground .', 'https://www.fs.usda.gov/recarea/mtnf/recarea/?recid=84211', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '84291', 'Sutton Bluff ATV 11 Trailhead', 'trailhead', 37.468771, -91.075829, null, 'Mark Twain National Forest', 'This trailhead functions as a staging area for OHVs for the Sutton Bluff Trail system. The Sutton Bluff ATV, UTV, and Motorcycle Area is located within the rugged river breaks of the West Fork of the Black River. The segmented trails are accessed via county roads and Forest Service system roads, and total approximately 45 miles. There are varying levels of difficulty over each segment, following forested ridge tops and crossing deep hollows. State regulations apply on all vehicles using public roads. Trail use permits are required and are for ATVs, UTVs and motorcycles only. No ATVs, UTVs or…', 'https://www.fs.usda.gov/recarea/mtnf/recarea/?recid=84291', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '84292', 'Sutton Bluff ATV 4 & 14 Trailhead', 'trailhead', 37.498893, -90.998459, null, 'Mark Twain National Forest', 'This trailhead functions as a staging area for OHVs for the Sutton Bluff Trail system. The Sutton Bluff ATV, UTV, and Motorcycle Area is located within the rugged river breaks of the West Fork of the Black River. The segmented trails are accessed via county roads and Forest Service system roads, and total approximately 45 miles. There are varying levels of difficulty over each segment, following forested ridge tops and crossing deep hollows. State regulations apply on all vehicles using public roads. Trail use permits are required and are for ATVs, UTVs and motorcycles only. No ATVs, UTVs or…', 'https://www.fs.usda.gov/recarea/mtnf/recarea/?recid=84292', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '84293', 'Sutton Bluff ATV 8 Trailhead', 'trailhead', 37.482459, -90.946508, null, 'Mark Twain National Forest', 'This trailhead functions as a staging area for OHVs for the Sutton Bluff Trail system. The Sutton Bluff ATV, UTV, and Motorcycle Area is located within the rugged river breaks of the West Fork of the Black River. The segmented trails are accessed via county roads and Forest Service system roads, and total approximately 45 miles. There are varying levels of difficulty over each segment, following forested ridge tops and crossing deep hollows. State regulations apply on all vehicles using public roads. Trail use permits are required and are for ATVs, UTVs and motorcycles only. No ATVs, UTVs or…', 'https://www.fs.usda.gov/recarea/mtnf/recarea/?recid=84293', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '84650', 'Morrison Divide North Trailhead', 'trailhead', 40.172340, -106.746970, null, 'Medicine Bow-Routt NFs and Thunder Basin NG', 'This Trailhead serves as one of two access points to the Morrison Divide Trail No. 1774. This 13.3 mile route climbs Green Ridge and grants access to the Muddy Slide overlook at an elevation of 10,258 feet. This stopping point offers spectacular views of the Morrison Creek Valley to the East and overlooks the Muddy Slide, a historic landslide. The trail experiences heavy ATV/OHV use during hunting season and is popular with hikers and mountain bikers during summer months. This trail is closed to any vehicles over 50 in width . Please tread lightly and do not ride off the designated route.…', 'https://www.fs.usda.gov/recarea/mbr/recarea/?recid=84650', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '9175', 'Deadhorse Trailhead', 'trailhead', 41.033706, -110.366206, null, 'Uinta-Wasatch-Cache National Forest', 'The trailhead has 4 campsite units', 'https://www.fs.usda.gov/recarea/uwcnf/recarea/?recid=9175', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '9532', 'Murdock Basin ATV Trailhead', 'trailhead', 40.633600, -110.932500, null, 'Uinta-Wasatch-Cache National Forest', 'Trailhead', 'https://www.fs.usda.gov/recarea/uwcnf/recarea/?recid=9532', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '9733', 'Taylor Fork ATV Trailhead', 'trailhead', 40.614637, -111.129756, null, 'Uinta-Wasatch-Cache National Forest', 'This trailhead is now combined with Shingle Creek. It is located along the Mirror Lake Scenic Highway.', 'https://www.fs.usda.gov/recarea/uwcnf/recarea/?recid=9733', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service'),
  ('usfs', '9834', 'Wolverine ATV Trailhead/Campground', 'trailhead', 40.846399, -110.814763, null, 'Uinta-Wasatch-Cache National Forest', 'This timbered trailhead is popular for hiking. Dry camp at ATV trailhead. This campground has not water available', 'https://www.fs.usda.gov/recarea/uwcnf/recarea/?recid=9834', array['ATV', 'UTV', 'Dirt Bike', '4x4']::text[], 'public domain', 'US Forest Service')
